   548→        if (match_token(parser, TOK_ASSIGN)) {
   549→            advance(parser);
   550→            ast->right = parse_expression(parser);
   551→        }
   552→
   553→        consume(parser, TOK_SEMICOLON);
   554→        return ast;
   555→    }
   556→
   557→    if (match_token(parser, TOK_LET)) {
   558→        advance(parser);
   559→
   560→        if (!match_token(parser, TOK_IDENT)) {
   561→            fprintf(stderr, "Error: Expected identifier\n");
   562→            return ast;
   563→        }
   564→        strcpy(ast->name, current_token(parser)->name);
   565→        advance(parser);
   566→
   567→        if (!consume(parser, TOK_ASSIGN)) {
   568→            fprintf(stderr, "Error: Expected '='\n");
   569→            return ast;
   570→        }
   571→
   572→        ast->right = parse_expression(parser);
   573→        consume(parser, TOK_SEMICOLON);
   574→        return ast;
   575→    }
   576→
   577→    if (match_token(parser, TOK_RETURN)) {
   578→        advance(parser);
   579→        ast->type = AST_RETURN;
   580→
   581→        if (!match_token(parser, TOK_SEMICOLON)) {
   582→            ast->right = parse_expression(parser);
   583→        }
   584→
   585→        consume(parser, TOK_SEMICOLON);
   586→        return ast;
   587→    }
   588→
   589→    if (match_token(parser, TOK_IF)) {
   590→        advance(parser);
   591→        ast->type = AST_IF;
   592→
   593→        if (!consume(parser, TOK_LPAREN)) {
   594→            fprintf(stderr, "Error: Expected '('\n");
   595→            return ast;
   596→        }
   597→        ast->left = parse_expression(parser);
   598→        if (!consume(parser, TOK_RPAREN)) {
   599→            fprintf(stderr, "Error: Expected ')'\n");
   600→            return ast;
   601→        }
   602→
   603→        if (!consume(parser, TOK_LBRACE)) {
   604→            fprintf(stderr, "Error: Expected '{'\n");
   605→            return ast;
   606→        }
   607→        while (!match_token(parser, TOK_RBRACE)) {
   608→            parse_statement(parser);
   609→        }
   610→        consume(parser, TOK_RBRACE);
   611→
   612→        if (match_token(parser, TOK_ELSE)) {
   613→            advance(parser);
   614→            if (!consume(parser, TOK_LBRACE)) {
   615→                fprintf(stderr, "Error: Expected '{'\n");
   616→                return ast;
   617→            }
   618→            while (!match_token(parser, TOK_RBRACE)) {
   619→                parse_statement(parser);
   620→            }
   621→            consume(parser, TOK_RBRACE);
   622→        }
   623→
   624→        return ast;
   625→    }
   626→
   627→    if (match_token(parser, TOK_WHILE)) {
   628→        advance(parser);
   629→        ast->type = AST_WHILE;
   630→
   631→        if (!consume(parser, TOK_LPAREN)) {
   632→            fprintf(stderr, "Error: Expected '('\n");
   633→            return ast;
   634→        }
   635→        ast->left = parse_expression(parser);
   636→        if (!consume(parser, TOK_RPAREN)) {
   637→            fprintf(stderr, "Error: Expected ')'\n");
   638→            return ast;
   639→        }
   640→
   641→        if (!consume(parser, TOK_LBRACE)) {
   642→            fprintf(stderr, "Error: Expected '{'\n");
   643→            return ast;
   644→        }
   645→        while (!match_token(parser, TOK_RBRACE)) {
   646→            parse_statement(parser);
   647→        }
   648→        consume(parser, TOK_RBRACE);
   649→
   650→        return ast;
   651→    }
   652→
   653→    // Expression statement
   654→    ast->right = parse_expression(parser);
   655→    consume(parser, TOK_SEMICOLON);
   656→
   657→    return ast;
   658→}
   659→
   660→// Parse an expression
   661→ASTNode* parse_expression(Parser *parser) {
   662→    ASTNode *left = parse_term(parser);
   663→
   664→    while (match_token(parser, TOK_PLUS) || match_token(parser, TOK_MINUS)) {
   665→        ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
   666→        ast->type = AST_BINOP;
   667→        ast->op = current_token(parser)->type;
   668→        advance(parser);
   669→
   670→        ast->left = left;
   671→        ast->right = parse_term(parser);
   672→        left = ast;
   673→    }
   674→
   675→    return left;
   676→}
   677→
   678→// Parse a term
   679→ASTNode* parse_term(Parser *parser) {
   680→    ASTNode *left = parse_primary(parser);
   681→
   682→    while (match_token(parser, TOK_STAR) || match_token(parser, TOK_SLASH)) {
   683→        ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
   684→        ast->type = AST_BINOP;
   685→        ast->op = current_token(parser)->type;
   686→        advance(parser);
   687→
   688→        ast->left = left;
   689→        ast->right = parse_primary(parser);
   690→        left = ast;
   691→    }
   692→
   693→    return left;
   694→}
   695→
   696→// Parse a primary
   697→ASTNode* parse_primary(Parser *parser) {
   698→    if (match_token(parser, TOK_INT)) {
   699→        ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
   700→        ast->type = AST_LITERAL;
   701→        ast->value = current_token(parser)->value;
   702→        advance(parser);
   703→        return ast;
   704→    }
   705→
   706→    if (match_token(parser, TOK_IDENT)) {
   707→        ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
   708→        ast->type = AST_IDENT;
   709→        strcpy(ast->name, current_token(parser)->name);
   710→        advance(parser);
   711→
   712→        if (match_token(parser, TOK_LPAREN)) {
   713→            ast->type = AST_CALL;
   714→            advance(parser);
   715→
   716→            ast->children = (ASTNode **)malloc(sizeof(ASTNode *) * 100);
   717→            ast->children_count = 0;
   718→
   719→            while (!match_token(parser, TOK_RPAREN) && !match_token(parser, TOK_EOF)) {
   720→                ASTNode *arg = parse_expression(parser);
   721→                ast->children[ast->children_count++] = arg;
   722→
   723→                if (match_token(parser, TOK_COMMA)) {
   724→                    advance(parser);
   725→                }
   726→            }
   727→
   728→            consume(parser, TOK_RPAREN);
   729→        }
   730→
   731→        return ast;
   732→    }
   733→
   734→    if (match_token(parser, TOK_LPAREN)) {
   735→        advance(parser);
   736→        ASTNode *expr = parse_expression(parser);
   737→        consume(parser, TOK_RPAREN);
   738→        return expr;
   739→    }
   740→
   741→    ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
   742→    ast->type = 0;  // Invalid
   743→    return ast;
   744→}
   745→
   746→// ============================================================
   747→// Part 3: CODEGEN
   748→// ============================================================
   749→
   750→// Forward declarations
   751→char* codegen(ASTNode *ast);
   752→char* codegen_program(ASTNode *ast);
   753→char* codegen_function(ASTNode *ast);
   754→char* codegen_statement(ASTNode *ast);
   755→char* codegen_expression(ASTNode *ast);
   756→
   757→// Allocate output buffer
   758→#define OUTPUT_SIZE 1000000
   759→static char output_buffer[OUTPUT_SIZE];
   760→static int output_pos = 0;
   761→
   762→// Helper: Append string to output
   763→void append_output(const char *str) {
   764→    if (output_pos + strlen(str) < OUTPUT_SIZE) {
   765→        strcpy(output_buffer + output_pos, str);
   766→        output_pos += strlen(str);
   767→    }
   768→}
   769→
   770→// Generate C code for an AST
   771→char* codegen(ASTNode *ast) {
   772→    output_pos = 0;
   773→    memset(output_buffer, 0, OUTPUT_SIZE);
   774→
   775→    if (ast == NULL) {
   776→        return output_buffer;
   777→    }
   778→
   779→    if (ast->type == AST_PROGRAM) {
   780→        char *code = codegen_program(ast);
   781→        return code;
   782→    }
   783→
   784→    return output_buffer;
   785→}
   786→
   787→// Generate C code for a program
   788→char* codegen_program(ASTNode *ast) {
   789→    append_output("#include <stdio.h>\n");
   790→    append_output("#include <stdlib.h>\n");
   791→    append_output("#include <string.h>\n");
   792→    append_output("#include <stdint.h>\n\n");
   793→
   794→    // Forward declarations
   795→    append_output("// Forward declarations\n");
   796→    for (int i = 0; i < ast->children_count; i++) {
   797→        if (ast->children[i]->type == AST_FUNC) {
   798→            append_output("int ");
   799→            append_output(ast->children[i]->name);
   800→            append_output("(void);\n");
   801→        }
   802→    }
   803→    append_output("\n");
   804→
   805→    // Function implementations
   806→    append_output("// Function definitions\n");
   807→    for (int i = 0; i < ast->children_count; i++) {
   808→        if (ast->children[i]->type == AST_FUNC) {
   809→            char *func_code = codegen_function(ast->children[i]);
   810→            append_output(func_code);
   811→        }
   812→    }
   813→
   814→    // Main function
   815→    append_output("\nint main(void) {\n");
   816→    append_output("    return 0;\n");
   817→    append_output("}\n");
   818→
   819→    return output_buffer;
   820→}
   821→
   822→// Generate C code for a function
   823→char* codegen_function(ASTNode *ast) {
   824→    char buf[2048];
   825→    snprintf(buf, sizeof(buf), "int %s(void) {\n", ast->name);
   826→    append_output(buf);
   827→
   828→    // Function body
   829→    for (int i = 0; i < ast->children_count; i++) {
   830→        char *stmt_code = codegen_statement(ast->children[i]);
   831→        append_output(stmt_code);
   832→    }
   833→
   834→    append_output("    return 0;\n");
   835→    append_output("}\n\n");
   836→
   837→    return output_buffer;
   838→}
   839→
   840→// Generate C code for a statement
   841→char* codegen_statement(ASTNode *ast) {
   842→    static char stmt_buf[4096];
   843→    stmt_buf[0] = '\0';
   844→
   845→    if (ast == NULL) {
   846→        return stmt_buf;
   847→    }
   848→
   849→    if (ast->type == AST_VAR) {
   850→        snprintf(stmt_buf, sizeof(stmt_buf), "    int %s;\n", ast->name);
   851→    } else if (ast->type == AST_RETURN) {
   852→        snprintf(stmt_buf, sizeof(stmt_buf), "    return 0;\n");
   853→    } else if (ast->type == AST_IF) {
   854→        snprintf(stmt_buf, sizeof(stmt_buf), "    if (1) {\n    }\n");
   855→    } else if (ast->type == AST_WHILE) {
   856→        snprintf(stmt_buf, sizeof(stmt_buf), "    while (1) {\n    }\n");
   857→    } else {
   858→        snprintf(stmt_buf, sizeof(stmt_buf), "    // statement\n");
   859→    }
   860→
   861→    return stmt_buf;
   862→}
   863→
   864→// Generate C code for an expression
   865→char* codegen_expression(ASTNode *ast) {
   866→    static char expr_buf[2048];
   867→    expr_buf[0] = '\0';
   868→
   869→    if (ast == NULL) {
   870→        return expr_buf;
   871→    }
   872→
   873→    if (ast->type == AST_LITERAL) {
   874→        snprintf(expr_buf, sizeof(expr_buf), "%d", ast->value);
   875→    } else if (ast->type == AST_IDENT) {
   876→        snprintf(expr_buf, sizeof(expr_buf), "%s", ast->name);
   877→    } else if (ast->type == AST_BINOP) {
   878→        char op_str[10];
   879→        if (ast->op == TOK_PLUS) strcpy(op_str, "+");
   880→        else if (ast->op == TOK_MINUS) strcpy(op_str, "-");
   881→        else if (ast->op == TOK_STAR) strcpy(op_str, "*");
   882→        else if (ast->op == TOK_SLASH) strcpy(op_str, "/");
   883→        else strcpy(op_str, "?");
   884→
   885→        snprintf(expr_buf, sizeof(expr_buf), "(%s %s %s)",
   886→                 codegen_expression(ast->left),
   887→                 op_str,
   888→                 codegen_expression(ast->right));
   889→    } else if (ast->type == AST_CALL) {
   890→        snprintf(expr_buf, sizeof(expr_buf), "%s()", ast->name);
   891→    }
   892→
   893→    return expr_buf;
   894→}
   895→
   896→// ============================================================
   897→// Part 4: MAIN
   898→// ============================================================
   899→
   900→int main(int argc, char *argv[]) {
   901→    if (argc < 2) {
   902→        fprintf(stderr, "Usage: %s <input.fl>\n", argv[0]);
   903→        return 1;
   904→    }
   905→
   906→    // Read input file
   907→    FILE *file = fopen(argv[1], "r");
   908→    if (file == NULL) {
   909→        fprintf(stderr, "Error: Cannot open file '%s'\n", argv[1]);
   910→        return 1;
   911→    }
   912→
   913→    // Get file size
   914→    fseek(file, 0, SEEK_END);
   915→    int file_size = ftell(file);
   916→    fseek(file, 0, SEEK_SET);
   917→
   918→    // Read file content
   919→    char *input = (char *)malloc(file_size + 1);
   920→    fread(input, 1, file_size, file);
   921→    input[file_size] = '\0';
   922→    fclose(file);
   923→
   924→    // Tokenize
   925→    Lexer *lexer = tokenize(input);
   926→    printf("Tokens: %d\n", lexer->tokens_count);
   927→
   928→    // Parse
   929→    Parser parser;
   930→    parser.tokens = lexer->tokens;
   931→    parser.pos = 0;
   932→    parser.tokens_count = lexer->tokens_count;
   933→
   934→    ASTNode *ast = parse_program(&parser);
   935→    printf("AST: type=%d, children=%d\n", ast->type, ast->children_count);
   936→
   937→    // Codegen
   938→    char *c_code = codegen(ast);
   939→    printf("%s\n", c_code);
   940→
   941→    // Cleanup
   942→    free(input);
   943→    free(lexer->tokens);
   944→    free(lexer);
   945→
   946→    return 0;
   947→}
