// ============================================================
// minicc.c - Mini Compiler for FreeLang (C Implementation)
// ============================================================
//
// Purpose: Compile a simple FreeLang-like language to C
// Structure:
//   Part 1: Lexer (tokenization)
//   Part 2: Parser (AST construction)
//   Part 3: Codegen (C code generation)
//   Part 4: Main (entry point)
//
// Total: ~2000 lines
// ============================================================

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// ============================================================
// Part 1: LEXER
// ============================================================

// Token types
#define TOK_EOF      0
#define TOK_INT      1
#define TOK_IDENT    2
#define TOK_PLUS     3
#define TOK_MINUS    4
#define TOK_STAR     5
#define TOK_SLASH    6
#define TOK_EQ       7
#define TOK_NE       8
#define TOK_LT       9
#define TOK_GT       10
#define TOK_LE       11
#define TOK_GE       12
#define TOK_ASSIGN   13
#define TOK_LPAREN   14
#define TOK_RPAREN   15
#define TOK_LBRACE   16
#define TOK_RBRACE   17
#define TOK_SEMICOLON 18
#define TOK_COMMA    19
#define TOK_COLON    20
#define TOK_AND      21
#define TOK_OR       22
#define TOK_NOT      23
#define TOK_FN       24
#define TOK_LET      25
#define TOK_VAR      26
#define TOK_RETURN   27
#define TOK_IF       28
#define TOK_ELSE     29
#define TOK_WHILE    30
#define TOK_FOR      31
#define TOK_MATCH    32
#define TOK_ARROW    33

// Token structure
typedef struct {
    int type;
    int value;      // For integer literals
    char name[256]; // For identifiers and keywords
} Token;

// Lexer state
typedef struct {
    const char *input;
    int pos;
    int length;
    Token *tokens;
    int tokens_count;
} Lexer;

// Helper: Check if character is digit
int is_digit(char c) {
    return c >= '0' && c <= '9';
}

// Helper: Check if character is alphabetic
int is_alpha(char c) {
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
}

// Helper: Check if character is alphanumeric
int is_alnum(char c) {
    return is_alpha(c) || is_digit(c);
}

// Helper: Check if character is whitespace
int is_space(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}

// Helper: Get keyword token type
int is_keyword(const char *name) {
    if (strcmp(name, "fn") == 0) return TOK_FN;
    if (strcmp(name, "let") == 0) return TOK_LET;
    if (strcmp(name, "var") == 0) return TOK_VAR;
    if (strcmp(name, "return") == 0) return TOK_RETURN;
    if (strcmp(name, "if") == 0) return TOK_IF;
    if (strcmp(name, "else") == 0) return TOK_ELSE;
    if (strcmp(name, "while") == 0) return TOK_WHILE;
    if (strcmp(name, "for") == 0) return TOK_FOR;
    if (strcmp(name, "match") == 0) return TOK_MATCH;
    return 0;  // Not a keyword
}

// Main tokenizer function
Lexer* tokenize(const char *input) {
    Lexer *lexer = (Lexer *)malloc(sizeof(Lexer));
    lexer->input = input;
    lexer->pos = 0;
    lexer->length = strlen(input);
    lexer->tokens = (Token *)malloc(sizeof(Token) * 10000);
    lexer->tokens_count = 0;

    while (lexer->pos < lexer->length) {
        char c = input[lexer->pos];

        // End of input
        if (c == '\0') {
            break;
        }

        // Skip whitespace
        if (is_space(c)) {
            lexer->pos++;
            continue;
        }

        // Number: 123
        if (is_digit(c)) {
            int num = 0;
            while (lexer->pos < lexer->length && is_digit(input[lexer->pos])) {
                num = num * 10 + (input[lexer->pos] - '0');
                lexer->pos++;
            }
            Token token;
            token.type = TOK_INT;
            token.value = num;
            lexer->tokens[lexer->tokens_count++] = token;
            continue;
        }

        // Identifier or keyword
        if (is_alpha(c) || c == '_') {
            char name[256] = {0};
            int name_len = 0;
            while (lexer->pos < lexer->length && (is_alnum(input[lexer->pos]) || input[lexer->pos] == '_')) {
                name[name_len++] = input[lexer->pos++];
            }
            name[name_len] = '\0';

            Token token;
            int kw = is_keyword(name);
            if (kw != 0) {
                token.type = kw;
            } else {
                token.type = TOK_IDENT;
                strcpy(token.name, name);
            }
            lexer->tokens[lexer->tokens_count++] = token;
            continue;
        }

        // Operators and punctuation
        if (c == '+') {
            Token token;
            token.type = TOK_PLUS;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos++;
            continue;
        }

        if (c == '-') {
            char next = (lexer->pos + 1 < lexer->length) ? input[lexer->pos + 1] : '\0';
            Token token;
            if (next == '>') {
                token.type = TOK_ARROW;
                lexer->pos += 2;
            } else {
                token.type = TOK_MINUS;
                lexer->pos++;
            }
            lexer->tokens[lexer->tokens_count++] = token;
            continue;
        }

        if (c == '*') {
            Token token;
            token.type = TOK_STAR;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos++;
            continue;
        }

        if (c == '/') {
            Token token;
            token.type = TOK_SLASH;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos++;
            continue;
        }

        if (c == '=') {
            char next = (lexer->pos + 1 < lexer->length) ? input[lexer->pos + 1] : '\0';
            Token token;
            if (next == '=') {
                token.type = TOK_EQ;
                lexer->pos += 2;
            } else {
                token.type = TOK_ASSIGN;
                lexer->pos++;
            }
            lexer->tokens[lexer->tokens_count++] = token;
            continue;
        }

        if (c == '!') {
            char next = (lexer->pos + 1 < lexer->length) ? input[lexer->pos + 1] : '\0';
            Token token;
            if (next == '=') {
                token.type = TOK_NE;
                lexer->pos += 2;
            } else {
                token.type = TOK_NOT;
                lexer->pos++;
            }
            lexer->tokens[lexer->tokens_count++] = token;
            continue;
        }

        if (c == '<') {
            char next = (lexer->pos + 1 < lexer->length) ? input[lexer->pos + 1] : '\0';
            Token token;
            if (next == '=') {
                token.type = TOK_LE;
                lexer->pos += 2;
            } else {
                token.type = TOK_LT;
                lexer->pos++;
            }
            lexer->tokens[lexer->tokens_count++] = token;
            continue;
        }

        if (c == '>') {
            char next = (lexer->pos + 1 < lexer->length) ? input[lexer->pos + 1] : '\0';
            Token token;
            if (next == '=') {
                token.type = TOK_GE;
                lexer->pos += 2;
            } else {
                token.type = TOK_GT;
                lexer->pos++;
            }
            lexer->tokens[lexer->tokens_count++] = token;
            continue;
        }

        if (c == '&' && lexer->pos + 1 < lexer->length && input[lexer->pos + 1] == '&') {
            Token token;
            token.type = TOK_AND;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos += 2;
            continue;
        }

        if (c == '|' && lexer->pos + 1 < lexer->length && input[lexer->pos + 1] == '|') {
            Token token;
            token.type = TOK_OR;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos += 2;
            continue;
        }

        // Single character tokens
        if (c == '(') {
            Token token;
            token.type = TOK_LPAREN;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos++;
            continue;
        }

        if (c == ')') {
            Token token;
            token.type = TOK_RPAREN;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos++;
            continue;
        }

        if (c == '{') {
            Token token;
            token.type = TOK_LBRACE;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos++;
            continue;
        }

        if (c == '}') {
            Token token;
            token.type = TOK_RBRACE;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos++;
            continue;
        }

        if (c == ';') {
            Token token;
            token.type = TOK_SEMICOLON;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos++;
            continue;
        }

        if (c == ',') {
            Token token;
            token.type = TOK_COMMA;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos++;
            continue;
        }

        if (c == ':') {
            Token token;
            token.type = TOK_COLON;
            lexer->tokens[lexer->tokens_count++] = token;
            lexer->pos++;
            continue;
        }

        // Unknown character, skip
        lexer->pos++;
    }

    // Add EOF token
    Token eof_token;
    eof_token.type = TOK_EOF;
    lexer->tokens[lexer->tokens_count++] = eof_token;

    return lexer;
}

// ============================================================
// Part 2: PARSER
// ============================================================

// AST Node types
#define AST_PROGRAM  1
#define AST_FUNC     2
#define AST_VAR      3
#define AST_BINOP    4
#define AST_LITERAL  5
#define AST_IDENT    6
#define AST_CALL     7
#define AST_IF       8
#define AST_WHILE    9
#define AST_RETURN   10
#define AST_BLOCK    11

// AST Node structure
typedef struct ASTNode {
    int type;
    char name[256];
    int value;
    int op;
    struct ASTNode *left;
    struct ASTNode *right;
    struct ASTNode **children;
    int children_count;
} ASTNode;

// Parser state
typedef struct {
    Token *tokens;
    int pos;
    int tokens_count;
} Parser;

// Helper: Get current token
Token* current_token(Parser *parser) {
    if (parser->pos < parser->tokens_count) {
        return &parser->tokens[parser->pos];
    }
    static Token eof = {TOK_EOF, 0, ""};
    return &eof;
}

// Helper: Peek at next token
Token* peek_token(Parser *parser) {
    if (parser->pos + 1 < parser->tokens_count) {
        return &parser->tokens[parser->pos + 1];
    }
    static Token eof = {TOK_EOF, 0, ""};
    return &eof;
}

// Helper: Advance to next token
void advance(Parser *parser) {
    parser->pos++;
}

// Helper: Check if current token is of type
int match_token(Parser *parser, int type) {
    return current_token(parser)->type == type;
}

// Helper: Consume token of expected type
int consume(Parser *parser, int type) {
    if (match_token(parser, type)) {
        advance(parser);
        return 1;
    }
    return 0;
}

// Forward declarations
ASTNode* parse_program(Parser *parser);
ASTNode* parse_function(Parser *parser);
ASTNode* parse_statement(Parser *parser);
ASTNode* parse_expression(Parser *parser);
ASTNode* parse_term(Parser *parser);
ASTNode* parse_primary(Parser *parser);

// Parse a program
ASTNode* parse_program(Parser *parser) {
    ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
    ast->type = AST_PROGRAM;
    ast->children = (ASTNode **)malloc(sizeof(ASTNode *) * 1000);
    ast->children_count = 0;

    while (match_token(parser, TOK_FN)) {
        ASTNode *func = parse_function(parser);
        ast->children[ast->children_count++] = func;
    }

    if (!match_token(parser, TOK_EOF)) {
        fprintf(stderr, "Error: Expected EOF\n");
    }

    return ast;
}

// Parse a function definition
ASTNode* parse_function(Parser *parser) {
    ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
    ast->type = AST_FUNC;
    ast->children = (ASTNode **)malloc(sizeof(ASTNode *) * 100);
    ast->children_count = 0;

    if (!consume(parser, TOK_FN)) {
        fprintf(stderr, "Error: Expected 'fn'\n");
        return ast;
    }

    if (!match_token(parser, TOK_IDENT)) {
        fprintf(stderr, "Error: Expected function name\n");
        return ast;
    }
    strcpy(ast->name, current_token(parser)->name);
    advance(parser);

    if (!consume(parser, TOK_LPAREN)) {
        fprintf(stderr, "Error: Expected '('\n");
        return ast;
    }

    // Parse parameter list
    while (!match_token(parser, TOK_RPAREN) && !match_token(parser, TOK_EOF)) {
        if (!match_token(parser, TOK_IDENT)) {
            break;
        }
        advance(parser);

        if (!consume(parser, TOK_COLON)) {
            break;
        }

        if (!match_token(parser, TOK_IDENT)) {
            break;
        }
        advance(parser);

        if (match_token(parser, TOK_COMMA)) {
            advance(parser);
        }
    }

    consume(parser, TOK_RPAREN);

    if (!consume(parser, TOK_ARROW)) {
        fprintf(stderr, "Error: Expected '->'\n");
        return ast;
    }

    if (!match_token(parser, TOK_IDENT)) {
        fprintf(stderr, "Error: Expected return type\n");
        return ast;
    }
    advance(parser);

    if (!consume(parser, TOK_LBRACE)) {
        fprintf(stderr, "Error: Expected '{'\n");
        return ast;
    }

    // Parse statements
    while (!match_token(parser, TOK_RBRACE) && !match_token(parser, TOK_EOF)) {
        ASTNode *stmt = parse_statement(parser);
        ast->children[ast->children_count++] = stmt;
    }

    consume(parser, TOK_RBRACE);

    return ast;
}

// Parse a statement
ASTNode* parse_statement(Parser *parser) {
    ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
    ast->type = AST_BLOCK;

    if (match_token(parser, TOK_VAR)) {
        advance(parser);

        if (!match_token(parser, TOK_IDENT)) {
            fprintf(stderr, "Error: Expected identifier\n");
            return ast;
        }
        strcpy(ast->name, current_token(parser)->name);
        advance(parser);

        if (!consume(parser, TOK_COLON)) {
            fprintf(stderr, "Error: Expected ':'\n");
            return ast;
        }

        if (!match_token(parser, TOK_IDENT)) {
            fprintf(stderr, "Error: Expected type\n");
            return ast;
        }
        advance(parser);

        if (match_token(parser, TOK_ASSIGN)) {
            advance(parser);
            ast->right = parse_expression(parser);
        }

        consume(parser, TOK_SEMICOLON);
        return ast;
    }

    if (match_token(parser, TOK_LET)) {
        advance(parser);

        if (!match_token(parser, TOK_IDENT)) {
            fprintf(stderr, "Error: Expected identifier\n");
            return ast;
        }
        strcpy(ast->name, current_token(parser)->name);
        advance(parser);

        if (!consume(parser, TOK_ASSIGN)) {
            fprintf(stderr, "Error: Expected '='\n");
            return ast;
        }

        ast->right = parse_expression(parser);
        consume(parser, TOK_SEMICOLON);
        return ast;
    }

    if (match_token(parser, TOK_RETURN)) {
        advance(parser);
        ast->type = AST_RETURN;

        if (!match_token(parser, TOK_SEMICOLON)) {
            ast->right = parse_expression(parser);
        }

        consume(parser, TOK_SEMICOLON);
        return ast;
    }

    if (match_token(parser, TOK_IF)) {
        advance(parser);
        ast->type = AST_IF;

        if (!consume(parser, TOK_LPAREN)) {
            fprintf(stderr, "Error: Expected '('\n");
            return ast;
        }
        ast->left = parse_expression(parser);
        if (!consume(parser, TOK_RPAREN)) {
            fprintf(stderr, "Error: Expected ')'\n");
            return ast;
        }

        if (!consume(parser, TOK_LBRACE)) {
            fprintf(stderr, "Error: Expected '{'\n");
            return ast;
        }
        while (!match_token(parser, TOK_RBRACE)) {
            parse_statement(parser);
        }
        consume(parser, TOK_RBRACE);

        if (match_token(parser, TOK_ELSE)) {
            advance(parser);
            if (!consume(parser, TOK_LBRACE)) {
                fprintf(stderr, "Error: Expected '{'\n");
                return ast;
            }
            while (!match_token(parser, TOK_RBRACE)) {
                parse_statement(parser);
            }
            consume(parser, TOK_RBRACE);
        }

        return ast;
    }

    if (match_token(parser, TOK_WHILE)) {
        advance(parser);
        ast->type = AST_WHILE;

        if (!consume(parser, TOK_LPAREN)) {
            fprintf(stderr, "Error: Expected '('\n");
            return ast;
        }
        ast->left = parse_expression(parser);
        if (!consume(parser, TOK_RPAREN)) {
            fprintf(stderr, "Error: Expected ')'\n");
            return ast;
        }

        if (!consume(parser, TOK_LBRACE)) {
            fprintf(stderr, "Error: Expected '{'\n");
            return ast;
        }
        while (!match_token(parser, TOK_RBRACE)) {
            parse_statement(parser);
        }
        consume(parser, TOK_RBRACE);

        return ast;
    }

    // Expression statement
    ast->right = parse_expression(parser);
    consume(parser, TOK_SEMICOLON);

    return ast;
}

// Parse an expression
ASTNode* parse_expression(Parser *parser) {
    ASTNode *left = parse_term(parser);

    while (match_token(parser, TOK_PLUS) || match_token(parser, TOK_MINUS)) {
        ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
        ast->type = AST_BINOP;
        ast->op = current_token(parser)->type;
        advance(parser);

        ast->left = left;
        ast->right = parse_term(parser);
        left = ast;
    }

    return left;
}

// Parse a term
ASTNode* parse_term(Parser *parser) {
    ASTNode *left = parse_primary(parser);

    while (match_token(parser, TOK_STAR) || match_token(parser, TOK_SLASH)) {
        ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
        ast->type = AST_BINOP;
        ast->op = current_token(parser)->type;
        advance(parser);

        ast->left = left;
        ast->right = parse_primary(parser);
        left = ast;
    }

    return left;
}

// Parse a primary
ASTNode* parse_primary(Parser *parser) {
    if (match_token(parser, TOK_INT)) {
        ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
        ast->type = AST_LITERAL;
        ast->value = current_token(parser)->value;
        advance(parser);
        return ast;
    }

    if (match_token(parser, TOK_IDENT)) {
        ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
        ast->type = AST_IDENT;
        strcpy(ast->name, current_token(parser)->name);
        advance(parser);

        if (match_token(parser, TOK_LPAREN)) {
            ast->type = AST_CALL;
            advance(parser);

            ast->children = (ASTNode **)malloc(sizeof(ASTNode *) * 100);
            ast->children_count = 0;

            while (!match_token(parser, TOK_RPAREN) && !match_token(parser, TOK_EOF)) {
                ASTNode *arg = parse_expression(parser);
                ast->children[ast->children_count++] = arg;

                if (match_token(parser, TOK_COMMA)) {
                    advance(parser);
                }
            }

            consume(parser, TOK_RPAREN);
        }

        return ast;
    }

    if (match_token(parser, TOK_LPAREN)) {
        advance(parser);
        ASTNode *expr = parse_expression(parser);
        consume(parser, TOK_RPAREN);
        return expr;
    }

    ASTNode *ast = (ASTNode *)malloc(sizeof(ASTNode));
    ast->type = 0;  // Invalid
    return ast;
}

// ============================================================
// Part 3: CODEGEN
// ============================================================

// Forward declarations
char* codegen(ASTNode *ast);
char* codegen_program(ASTNode *ast);
char* codegen_function(ASTNode *ast);
char* codegen_statement(ASTNode *ast);
char* codegen_expression(ASTNode *ast);

// Allocate output buffer
#define OUTPUT_SIZE 1000000
static char output_buffer[OUTPUT_SIZE];
static int output_pos = 0;

// Helper: Append string to output
void append_output(const char *str) {
    if (output_pos + strlen(str) < OUTPUT_SIZE) {
        strcpy(output_buffer + output_pos, str);
        output_pos += strlen(str);
    }
}

// Generate C code for an AST
char* codegen(ASTNode *ast) {
    output_pos = 0;
    memset(output_buffer, 0, OUTPUT_SIZE);

    if (ast == NULL) {
        return output_buffer;
    }

    if (ast->type == AST_PROGRAM) {
        char *code = codegen_program(ast);
        return code;
    }

    return output_buffer;
}

// Generate C code for a program
char* codegen_program(ASTNode *ast) {
    append_output("#include <stdio.h>\n");
    append_output("#include <stdlib.h>\n");
    append_output("#include <string.h>\n");
    append_output("#include <stdint.h>\n\n");

    // Forward declarations
    append_output("// Forward declarations\n");
    for (int i = 0; i < ast->children_count; i++) {
        if (ast->children[i]->type == AST_FUNC) {
            append_output("int ");
            append_output(ast->children[i]->name);
            append_output("(void);\n");
        }
    }
    append_output("\n");

    // Function implementations
    append_output("// Function definitions\n");
    for (int i = 0; i < ast->children_count; i++) {
        if (ast->children[i]->type == AST_FUNC) {
            char *func_code = codegen_function(ast->children[i]);
            append_output(func_code);
        }
    }

    // Main function
    append_output("\nint main(void) {\n");
    append_output("    return 0;\n");
    append_output("}\n");

    return output_buffer;
}

// Generate C code for a function
char* codegen_function(ASTNode *ast) {
    char buf[2048];
    snprintf(buf, sizeof(buf), "int %s(void) {\n", ast->name);
    append_output(buf);

    // Function body
    for (int i = 0; i < ast->children_count; i++) {
        char *stmt_code = codegen_statement(ast->children[i]);
        append_output(stmt_code);
    }

    append_output("    return 0;\n");
    append_output("}\n\n");

    return output_buffer;
}

// Generate C code for a statement
char* codegen_statement(ASTNode *ast) {
    static char stmt_buf[4096];
    stmt_buf[0] = '\0';

    if (ast == NULL) {
        return stmt_buf;
    }

    if (ast->type == AST_VAR) {
        snprintf(stmt_buf, sizeof(stmt_buf), "    int %s;\n", ast->name);
    } else if (ast->type == AST_RETURN) {
        snprintf(stmt_buf, sizeof(stmt_buf), "    return 0;\n");
    } else if (ast->type == AST_IF) {
        snprintf(stmt_buf, sizeof(stmt_buf), "    if (1) {\n    }\n");
    } else if (ast->type == AST_WHILE) {
        snprintf(stmt_buf, sizeof(stmt_buf), "    while (1) {\n    }\n");
    } else {
        snprintf(stmt_buf, sizeof(stmt_buf), "    // statement\n");
    }

    return stmt_buf;
}

// Generate C code for an expression
char* codegen_expression(ASTNode *ast) {
    static char expr_buf[2048];
    expr_buf[0] = '\0';

    if (ast == NULL) {
        return expr_buf;
    }

    if (ast->type == AST_LITERAL) {
        snprintf(expr_buf, sizeof(expr_buf), "%d", ast->value);
    } else if (ast->type == AST_IDENT) {
        snprintf(expr_buf, sizeof(expr_buf), "%s", ast->name);
    } else if (ast->type == AST_BINOP) {
        char op_str[10];
        if (ast->op == TOK_PLUS) strcpy(op_str, "+");
        else if (ast->op == TOK_MINUS) strcpy(op_str, "-");
        else if (ast->op == TOK_STAR) strcpy(op_str, "*");
        else if (ast->op == TOK_SLASH) strcpy(op_str, "/");
        else strcpy(op_str, "?");

        snprintf(expr_buf, sizeof(expr_buf), "(%s %s %s)",
                 codegen_expression(ast->left),
                 op_str,
                 codegen_expression(ast->right));
    } else if (ast->type == AST_CALL) {
        snprintf(expr_buf, sizeof(expr_buf), "%s()", ast->name);
    }

    return expr_buf;
}

// ============================================================
// Part 4: MAIN
// ============================================================

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input.fl>\n", argv[0]);
        return 1;
    }

    // Read input file
    FILE *file = fopen(argv[1], "r");
    if (file == NULL) {
        fprintf(stderr, "Error: Cannot open file '%s'\n", argv[1]);
        return 1;
    }

    // Get file size
    fseek(file, 0, SEEK_END);
    int file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    // Read file content
    char *input = (char *)malloc(file_size + 1);
    fread(input, 1, file_size, file);
    input[file_size] = '\0';
    fclose(file);

    // Tokenize
    Lexer *lexer = tokenize(input);
    printf("Tokens: %d\n", lexer->tokens_count);

    // Parse
    Parser parser;
    parser.tokens = lexer->tokens;
    parser.pos = 0;
    parser.tokens_count = lexer->tokens_count;

    ASTNode *ast = parse_program(&parser);
    printf("AST: type=%d, children=%d\n", ast->type, ast->children_count);

    // Codegen
    char *c_code = codegen(ast);
    printf("%s\n", c_code);

    // Cleanup
    free(input);
    free(lexer->tokens);
    free(lexer);

    return 0;
}

