// Helper: Check if character is digit
fn is_digit(c: i64) -> i64 {
    if (c >= 48 && c <= 57) {
        return 1;  // '0' to '9'
    }
    return 0;
}

// Helper: Check if character is alphabetic
fn is_alpha(c: i64) -> i64 {
    if ((c >= 65 && c <= 90) || (c >= 97 && c <= 122)) {
        return 1;  // 'A-Z' or 'a-z'
    }
    return 0;
}

// Helper: Check if character is alphanumeric
fn is_alnum(c: i64) -> i64 {
    if (is_alpha(c) == 1 || is_digit(c) == 1) {
        return 1;
    }
    return 0;
}

// Helper: Check if character is whitespace
fn is_space(c: i64) -> i64 {
    if (c == 32 || c == 9 || c == 10 || c == 13) {
        return 1;  // space, tab, newline, carriage return
    }
    return 0;
}

// Helper: Get string length
