// Helper: Check if identifier is keyword
fn is_keyword(name: string) -> i64 {
    if (str_cmp(name, "fn") == 1) return TOK_FN;
    if (str_cmp(name, "let") == 1) return TOK_LET;
    if (str_cmp(name, "var") == 1) return TOK_VAR;
    if (str_cmp(name, "return") == 1) return TOK_RETURN;
    if (str_cmp(name, "if") == 1) return TOK_IF;
