            count = count + 1;
            continue;
        }

        // Identifier or keyword
        if (is_alpha(c) == 1 || c == 95) {  // '_' = 95
            var name: string = "";
            var name_len: i64 = 0;
            while (i < 10000 && (is_alnum(c) == 1 || c == 95)) {
                // Append c to name (simplified)
                name_len = name_len + 1;
                i = i + 1;
                c = 0;  // Would be input[i]
            }
            // Check if keyword
            var kw: i64 = is_keyword(name);
            if (kw != 0) {
                tokens[count].type = kw;
            } else {
                tokens[count].type = TOK_IDENT;
                tokens[count].name = name;
            }
            count = count + 1;
            continue;
        }

        // Operators and punctuation
        if (c == 43) {  // '+'
            tokens[count].type = TOK_PLUS;
            i = i + 1;
            count = count + 1;
            continue;
        }

        if (c == 45) {  // '-'
            var next: i64 = 0;  // input[i+1]
            if (next == 62) {  // '-' followed by '>' = '->'
                tokens[count].type = TOK_ARROW;
                i = i + 2;
            } else {
                tokens[count].type = TOK_MINUS;
                i = i + 1;
            }
            count = count + 1;
            continue;
        }

        if (c == 42) {  // '*'
            tokens[count].type = TOK_STAR;
            i = i + 1;
            count = count + 1;
            continue;
        }

        if (c == 47) {  // '/'
            tokens[count].type = TOK_SLASH;
            i = i + 1;
            count = count + 1;
            continue;
        }

        if (c == 61) {  // '='
            var next: i64 = 0;  // input[i+1]
            if (next == 61) {  // '=='
                tokens[count].type = TOK_EQ;
                i = i + 2;
            } else {
                tokens[count].type = TOK_ASSIGN;
                i = i + 1;
            }
            count = count + 1;
            continue;
        }

        if (c == 33) {  // '!'
            var next: i64 = 0;  // input[i+1]
            if (next == 61) {  // '!='
                tokens[count].type = TOK_NE;
                i = i + 2;
            } else {
                tokens[count].type = TOK_NOT;
                i = i + 1;
            }
            count = count + 1;
            continue;
        }

        if (c == 60) {  // '<'
            var next: i64 = 0;  // input[i+1]
            if (next == 61) {  // '<='
                tokens[count].type = TOK_LE;
                i = i + 2;
            } else {
                tokens[count].type = TOK_LT;
                i = i + 1;
            }
            count = count + 1;
            continue;
        }

        if (c == 62) {  // '>'
            var next: i64 = 0;  // input[i+1]
            if (next == 61) {  // '>='
                tokens[count].type = TOK_GE;
                i = i + 2;
            } else {
                tokens[count].type = TOK_GT;
                i = i + 1;
            }
            count = count + 1;
            continue;
        }

        if (c == 38 && next == 38) {  // '&&'
            tokens[count].type = TOK_AND;
            i = i + 2;
            count = count + 1;
            continue;
        }

        if (c == 124 && next == 124) {  // '||'
            tokens[count].type = TOK_OR;
            i = i + 2;
            count = count + 1;
            continue;
        }

        // Single character tokens
        if (c == 40) {  // '('
            tokens[count].type = TOK_LPAREN;
            i = i + 1;
            count = count + 1;
            continue;
        }

        if (c == 41) {  // ')'
            tokens[count].type = TOK_RPAREN;
            i = i + 1;
            count = count + 1;
            continue;
        }

        if (c == 123) {  // '{'
            tokens[count].type = TOK_LBRACE;
            i = i + 1;
            count = count + 1;
            continue;
        }

        if (c == 125) {  // '}'
            tokens[count].type = TOK_RBRACE;
            i = i + 1;
            count = count + 1;
            continue;
        }

        if (c == 59) {  // ';'
            tokens[count].type = TOK_SEMICOLON;
            i = i + 1;
            count = count + 1;
            continue;
        }

        if (c == 44) {  // ','
            tokens[count].type = TOK_COMMA;
            i = i + 1;
            count = count + 1;
            continue;
        }

        if (c == 58) {  // ':'
            tokens[count].type = TOK_COLON;
            i = i + 1;
            count = count + 1;
            continue;
        }

        // Unknown character, skip
        i = i + 1;
    }

    // Add EOF token
    tokens[count].type = TOK_EOF;
    count = count + 1;

    return tokens;
}

// ============================================================
// Part 2: PARSER (AST Construction)
// ============================================================

// AST Node types
var AST_PROGRAM: i64 = 1;
var AST_FUNC: i64 = 2;
var AST_VAR: i64 = 3;
var AST_BINOP: i64 = 4;
var AST_LITERAL: i64 = 5;
var AST_IDENT: i64 = 6;
var AST_CALL: i64 = 7;
var AST_IF: i64 = 8;
var AST_WHILE: i64 = 9;
var AST_RETURN: i64 = 10;
var AST_BLOCK: i64 = 11;

struct ASTNode {
    type: i64,
    name: string,
    value: i64,
    op: i64,
}

struct Parser {
    tokens: [Token],
    pos: i64,
}

// ============================================================
// Parser Helper Functions
// ============================================================

// Get current token
fn current_token(parser: Parser) -> Token {
    var token: Token;
    // Simplified: would be parser.tokens[parser.pos]
    return token;
}

// Peek at next token without advancing
fn peek_token(parser: Parser) -> Token {
    var token: Token;
    // Simplified: would be parser.tokens[parser.pos + 1]
    return token;
}

// Advance to next token
fn advance(parser: Parser) -> i64 {
    parser.pos = parser.pos + 1;
    return parser.pos;
}

// Check if current token is of type
fn match_token(parser: Parser, type_: i64) -> i64 {
    var token: Token;
    token = current_token(parser);
    if (token.type == type_) {
        return 1;
    }
    return 0;
}

// Consume token of expected type
fn consume(parser: Parser, type_: i64) -> i64 {
    if (match_token(parser, type_) == 1) {
        advance(parser);
        return 1;
    }
    return 0;  // Error: unexpected token
}

// ============================================================
// Parser Functions
// ============================================================

// Parse a program: [function_list]
// program = function*
fn parse_program(tokens: [Token]) -> ASTNode {
    var ast: ASTNode;
    var parser: Parser;
    var count: i64 = 0;
    var func: ASTNode;

    parser.tokens = tokens;
    parser.pos = 0;

    ast.type = AST_PROGRAM;

    // Parse function declarations
    while (match_token(parser, TOK_FN) == 1) {
        func = parse_function(parser);
        // Would store in ast.children[count]
        count = count + 1;
    }

    // Expect EOF
    if (match_token(parser, TOK_EOF) == 0) {
        return ast;  // Error: expected EOF
    }

    return ast;
}

// Parse a function definition
// function = 'fn' identifier '(' parameters ')' '->' type '{' statement* '}'
fn parse_function(parser: Parser) -> ASTNode {
    var ast: ASTNode;
    var param_count: i64 = 0;
    var stmt: ASTNode;

    ast.type = AST_FUNC;

    // Expect 'fn'
    if (consume(parser, TOK_FN) == 0) {
        return ast;  // Error
    }

    // Parse function name
    if (match_token(parser, TOK_IDENT) == 0) {
        return ast;  // Error: expected identifier
    }
    // ast.name = current_token(parser).name
    advance(parser);

    // Parse parameters: '(' param_list ')'
    if (consume(parser, TOK_LPAREN) == 0) {
        return ast;  // Error
    }

    // Parse parameter list
    while (match_token(parser, TOK_RPAREN) == 0) {
        // param = identifier ':' type
        if (match_token(parser, TOK_IDENT) == 0) {
            break;  // Error
        }
        advance(parser);

        if (consume(parser, TOK_COLON) == 0) {
            break;  // Error
        }

        // Parse type
        if (match_token(parser, TOK_IDENT) == 0) {
            break;  // Error
        }
        advance(parser);

        param_count = param_count + 1;

        // Check for comma
        if (match_token(parser, TOK_COMMA) == 1) {
            advance(parser);
        }
    }

    // Consume ')'
    consume(parser, TOK_RPAREN);

    // Parse return type: '->' type
    if (consume(parser, TOK_ARROW) == 0) {
        return ast;  // Error
    }

    if (match_token(parser, TOK_IDENT) == 0) {
        return ast;  // Error: expected type
    }
    advance(parser);

    // Parse function body: '{' statement* '}'
    if (consume(parser, TOK_LBRACE) == 0) {
        return ast;  // Error
    }

    // Parse statements until '}'
    var stmt_count: i64 = 0;
    while (match_token(parser, TOK_RBRACE) == 0 && match_token(parser, TOK_EOF) == 0) {
        stmt = parse_statement(parser);
        // Would store in ast.body[stmt_count]
        stmt_count = stmt_count + 1;
    }

    // Consume '}'
    consume(parser, TOK_RBRACE);

    return ast;
}

// Parse a statement
// statement = var_decl | assignment | return_stmt | if_stmt | while_stmt | block
fn parse_statement(parser: Parser) -> ASTNode {
    var ast: ASTNode;
    var expr: ASTNode;

    ast.type = AST_BLOCK;

    // 'var' declaration: var name: type = expr;
    if (match_token(parser, TOK_VAR) == 1) {
        advance(parser);

        // Parse name
        if (match_token(parser, TOK_IDENT) == 0) {
            return ast;  // Error
        }
        advance(parser);

        // Parse type
        if (consume(parser, TOK_COLON) == 0) {
            return ast;  // Error
        }
        if (match_token(parser, TOK_IDENT) == 0) {
            return ast;  // Error: expected type
        }
        advance(parser);

        // Parse optional initialization
        if (match_token(parser, TOK_ASSIGN) == 1) {
            advance(parser);
            expr = parse_expression(parser);
        }

        // Consume ';'
        consume(parser, TOK_SEMICOLON);
        return ast;
    }

    // 'let' declaration: let name = expr;
    if (match_token(parser, TOK_LET) == 1) {
        advance(parser);

        if (match_token(parser, TOK_IDENT) == 0) {
            return ast;  // Error
        }
        advance(parser);

        if (consume(parser, TOK_ASSIGN) == 0) {
            return ast;  // Error
        }

        expr = parse_expression(parser);
        consume(parser, TOK_SEMICOLON);
        return ast;
    }

    // 'return' statement
    if (match_token(parser, TOK_RETURN) == 1) {
        advance(parser);
        ast.type = AST_RETURN;

        if (match_token(parser, TOK_SEMICOLON) == 0) {
            expr = parse_expression(parser);
        }

        consume(parser, TOK_SEMICOLON);
        return ast;
    }

    // 'if' statement
    if (match_token(parser, TOK_IF) == 1) {
        advance(parser);
        ast.type = AST_IF;

        // Parse condition
        if (consume(parser, TOK_LPAREN) == 0) {
            return ast;  // Error
        }
        expr = parse_expression(parser);
        if (consume(parser, TOK_RPAREN) == 0) {
            return ast;  // Error
        }

        // Parse then block
        if (consume(parser, TOK_LBRACE) == 0) {
            return ast;  // Error
        }
        while (match_token(parser, TOK_RBRACE) == 0) {
            parse_statement(parser);
        }
        consume(parser, TOK_RBRACE);

        // Parse else block (optional)
        if (match_token(parser, TOK_ELSE) == 1) {
            advance(parser);
            if (consume(parser, TOK_LBRACE) == 0) {
                return ast;  // Error
            }
            while (match_token(parser, TOK_RBRACE) == 0) {
                parse_statement(parser);
            }
            consume(parser, TOK_RBRACE);
        }

        return ast;
    }

    // 'while' statement
    if (match_token(parser, TOK_WHILE) == 1) {
        advance(parser);
        ast.type = AST_WHILE;

        if (consume(parser, TOK_LPAREN) == 0) {
            return ast;  // Error
        }
        expr = parse_expression(parser);
        if (consume(parser, TOK_RPAREN) == 0) {
            return ast;  // Error
        }

        if (consume(parser, TOK_LBRACE) == 0) {
            return ast;  // Error
        }
        while (match_token(parser, TOK_RBRACE) == 0) {
            parse_statement(parser);
        }
        consume(parser, TOK_RBRACE);

        return ast;
    }

    // Expression statement: expr;
    expr = parse_expression(parser);
    consume(parser, TOK_SEMICOLON);

    return ast;
}

// Parse an expression
// expression = term (('+' | '-') term)*
fn parse_expression(parser: Parser) -> ASTNode {
    var ast: ASTNode;
    var left: ASTNode;
    var right: ASTNode;
    var op: i64;

    ast.type = AST_BINOP;

    // Parse left operand (term)
    left = parse_term(parser);

    // Parse binary operators: + -
    while (match_token(parser, TOK_PLUS) == 1 || match_token(parser, TOK_MINUS) == 1) {
        if (match_token(parser, TOK_PLUS) == 1) {
            op = TOK_PLUS;
        } else {
            op = TOK_MINUS;
        }
        advance(parser);

        right = parse_term(parser);

        // Build binary operation node
        ast.op = op;
        // ast.left = left
        // ast.right = right
        left = ast;
    }

    return left;
}

// Parse a term: factor (('*' | '/') factor)*
fn parse_term(parser: Parser) -> ASTNode {
    var ast: ASTNode;
    var left: ASTNode;
    var right: ASTNode;
    var op: i64;

    ast.type = AST_BINOP;

    left = parse_primary(parser);

    while (match_token(parser, TOK_STAR) == 1 || match_token(parser, TOK_SLASH) == 1) {
        if (match_token(parser, TOK_STAR) == 1) {
            op = TOK_STAR;
        } else {
            op = TOK_SLASH;
        }
        advance(parser);

        right = parse_primary(parser);

        ast.op = op;
        // ast.left = left
        // ast.right = right
        left = ast;
    }

    return left;
}

// Parse a primary: number | identifier | '(' expression ')'
fn parse_primary(parser: Parser) -> ASTNode {
    var ast: ASTNode;
    var expr: ASTNode;

    // Integer literal
    if (match_token(parser, TOK_INT) == 1) {
        ast.type = AST_LITERAL;
        // ast.value = current_token(parser).value
        advance(parser);
        return ast;
    }

    // Identifier (or function call)
    if (match_token(parser, TOK_IDENT) == 1) {
        ast.type = AST_IDENT;
        // ast.name = current_token(parser).name
        advance(parser);

        // Check for function call: identifier '(' args ')'
        if (match_token(parser, TOK_LPAREN) == 1) {
            ast.type = AST_CALL;
            advance(parser);

            // Parse arguments
            var arg_count: i64 = 0;
            while (match_token(parser, TOK_RPAREN) == 0) {
                expr = parse_expression(parser);
                // ast.args[arg_count] = expr
                arg_count = arg_count + 1;

                if (match_token(parser, TOK_COMMA) == 1) {
                    advance(parser);
                }
            }

            consume(parser, TOK_RPAREN);
        }

        return ast;
    }

    // Parenthesized expression
    if (match_token(parser, TOK_LPAREN) == 1) {
        advance(parser);
        expr = parse_expression(parser);
        consume(parser, TOK_RPAREN);
        return expr;
    }

    // Error: unexpected token
    ast.type = 0;  // Invalid
    return ast;
}

// ============================================================
// Part 3: CODEGEN (C Code Generation)
// ============================================================

// Generate C code for an AST
fn codegen(ast: ASTNode) -> string {
    var output: string = "";

    // Headers
    output = output + "#include <stdio.h>\n";
    output = output + "#include <stdlib.h>\n";
    output = output + "#include <string.h>\n";
    output = output + "#include <stdint.h>\n";
    output = output + "\n";

    // Generate code based on AST type
    if (ast.type == AST_PROGRAM) {
        output = output + codegen_program(ast);
    }

    return output;
}

// Generate C code for a program node
fn codegen_program(ast: ASTNode) -> string {
    var output: string = "";

    // Generate function declarations (forward declarations)
    output = output + "// Forward declarations\n";
    // Would iterate through ast.functions

    // Generate function implementations
    output = output + "\n";
    output = output + "// Function definitions\n";
    // Would iterate through ast.functions and call codegen_function

    // Generate main function
    output = output + "\n";
    output = output + "int main(void) {\n";
    output = output + "    return 0;\n";
    output = output + "}\n";

    return output;
}

// Generate C code for a function node
fn codegen_function(ast: ASTNode) -> string {
    var output: string = "";

    // Return type: default to int
    output = output + "int ";

    // Function name
    // output = output + ast.name
    output = output + "(";

    // Parameters
    // Would iterate through ast.parameters
    output = output + ") {\n";

    // Function body
    // Would iterate through ast.body and call codegen_statement

    output = output + "    return 0;\n";
    output = output + "}\n";

    return output;
}

// Generate C code for a statement
fn codegen_statement(ast: ASTNode) -> string {
    var output: string = "";

    if (ast.type == AST_VAR) {
        output = output + "    int ";
        // output = output + ast.name
        output = output + ";\n";
    } else if (ast.type == AST_RETURN) {
        output = output + "    return ";
        // Would call codegen_expression for the return value
        output = output + "0;\n";
    } else if (ast.type == AST_IF) {
        output = output + "    if (";
        // Would call codegen_expression
        output = output + ") {\n";
        // Would generate body
        output = output + "    }\n";
    } else if (ast.type == AST_WHILE) {
        output = output + "    while (";
        // Would call codegen_expression
        output = output + ") {\n";
        // Would generate body
        output = output + "    }\n";
    } else {
        output = output + "    // Statement\n";
    }

    return output;
}

// Generate C code for an expression
fn codegen_expression(ast: ASTNode) -> string {
    var output: string = "";

    if (ast.type == AST_LITERAL) {
        // output = output + stringify(ast.value)
        output = output + "0";
    } else if (ast.type == AST_IDENT) {
        // output = output + ast.name
        output = output + "x";
    } else if (ast.type == AST_BINOP) {
        output = output + "(";
        // output = output + codegen_expression(ast.left)
        output = output + " ";

        // Operator
        if (ast.op == TOK_PLUS) {
            output = output + "+";
        } else if (ast.op == TOK_MINUS) {
            output = output + "-";
        } else if (ast.op == TOK_STAR) {
            output = output + "*";
        } else if (ast.op == TOK_SLASH) {
            output = output + "/";
        }

        output = output + " ";
        // output = output + codegen_expression(ast.right)
        output = output + ")";
    } else if (ast.type == AST_CALL) {
        // output = output + ast.name
        output = output + "func";
        output = output + "(";
        // Would iterate through arguments
        output = output + ")";
    }

    return output;
}

