// ============================================================
// minicc.c - Mini Compiler for FreeLang (Fixed v2)
// Compiles a subset of FreeLang to C
// ============================================================
//
// Structure:
//   Part 1: Lexer  - Input string -> Token array
//   Part 2: Parser - Token array  -> AST
//   Part 3: Codegen- AST          -> C code
//   Part 4: Main   - Pipeline
// ============================================================

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// ============================================================
// Part 1: LEXER
// ============================================================

#define TOK_EOF       0
#define TOK_INT       1
#define TOK_IDENT     2
#define TOK_PLUS      3
#define TOK_MINUS     4
#define TOK_STAR      5
#define TOK_SLASH     6
#define TOK_EQ        7   // ==
#define TOK_NE        8   // !=
#define TOK_LT        9   // <
#define TOK_GT        10  // >
#define TOK_LE        11  // <=
#define TOK_GE        12  // >=
#define TOK_ASSIGN    13  // =
#define TOK_LPAREN    14
#define TOK_RPAREN    15
#define TOK_LBRACE    16
#define TOK_RBRACE    17
#define TOK_SEMICOLON 18
#define TOK_COMMA     19
#define TOK_COLON     20
#define TOK_AND       21  // &&
#define TOK_OR        22  // ||
#define TOK_NOT       23  // !
#define TOK_FN        24
#define TOK_LET       25
#define TOK_VAR       26
#define TOK_RETURN    27
#define TOK_IF        28
#define TOK_ELSE      29
#define TOK_WHILE     30
#define TOK_FOR       31
#define TOK_MATCH     32
#define TOK_ARROW     33  // ->
#define TOK_STRING    34  // string literal

typedef struct {
    int   type;
    int   value;
    char  name[256];
    char  str_val[1024]; // for string literals
} Token;

typedef struct {
    const char *input;
    int         pos;
    int         length;
    Token      *tokens;
    int         tokens_count;
} Lexer;

static int char_is_digit(char c) { return c >= '0' && c <= '9'; }
static int char_is_alpha(char c) { return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z'); }
static int char_is_alnum(char c) { return char_is_alpha(c) || char_is_digit(c); }
static int char_is_space(char c) { return c == ' ' || c == '\t' || c == '\n' || c == '\r'; }

static int classify_keyword(const char *name) {
    if (strcmp(name, "fn")     == 0) return TOK_FN;
    if (strcmp(name, "let")    == 0) return TOK_LET;
    if (strcmp(name, "var")    == 0) return TOK_VAR;
    if (strcmp(name, "return") == 0) return TOK_RETURN;
    if (strcmp(name, "if")     == 0) return TOK_IF;
    if (strcmp(name, "else")   == 0) return TOK_ELSE;
    if (strcmp(name, "while")  == 0) return TOK_WHILE;
    if (strcmp(name, "for")    == 0) return TOK_FOR;
    if (strcmp(name, "match")  == 0) return TOK_MATCH;
    return 0;
}

Lexer* tokenize(const char *input) {
    Lexer *lex = (Lexer *)calloc(1, sizeof(Lexer));
    lex->input  = input;
    lex->length = (int)strlen(input);
    lex->tokens = (Token *)calloc(10000, sizeof(Token));

    while (lex->pos < lex->length) {
        char c = input[lex->pos];
        if (c == '\0') break;

        // Whitespace
        if (char_is_space(c)) { lex->pos++; continue; }

        // Line comments
        if (c == '/' && lex->pos + 1 < lex->length && input[lex->pos + 1] == '/') {
            while (lex->pos < lex->length && input[lex->pos] != '\n') lex->pos++;
            continue;
        }

        Token tok;
        memset(&tok, 0, sizeof(tok));

        // Number
        if (char_is_digit(c)) {
            while (lex->pos < lex->length && char_is_digit(input[lex->pos]))
                tok.value = tok.value * 10 + (input[lex->pos++] - '0');
            tok.type = TOK_INT;
            lex->tokens[lex->tokens_count++] = tok;
            continue;
        }

        // Identifier / keyword
        if (char_is_alpha(c) || c == '_') {
            int len = 0;
            while (lex->pos < lex->length &&
                   (char_is_alnum(input[lex->pos]) || input[lex->pos] == '_'))
                tok.name[len++] = input[lex->pos++];
            int kw = classify_keyword(tok.name);
            tok.type = kw ? kw : TOK_IDENT;
            lex->tokens[lex->tokens_count++] = tok;
            continue;
        }

        // String literal "..."
        if (c == '"') {
            lex->pos++;
            int len = 0;
            while (lex->pos < lex->length && input[lex->pos] != '"' && len < 1023) {
                if (input[lex->pos] == '\\' && lex->pos + 1 < lex->length) {
                    lex->pos++;
                    char esc = input[lex->pos++];
                    if      (esc == 'n')  tok.str_val[len++] = '\n';
                    else if (esc == 't')  tok.str_val[len++] = '\t';
                    else                  tok.str_val[len++] = esc;
                } else {
                    tok.str_val[len++] = input[lex->pos++];
                }
            }
            if (lex->pos < lex->length) lex->pos++; // closing "
            tok.type = TOK_STRING;
            lex->tokens[lex->tokens_count++] = tok;
            continue;
        }

        char next = (lex->pos + 1 < lex->length) ? input[lex->pos + 1] : 0;

        // Two-character operators
        if      (c == '-' && next == '>') { tok.type = TOK_ARROW;  lex->pos += 2; }
        else if (c == '=' && next == '=') { tok.type = TOK_EQ;     lex->pos += 2; }
        else if (c == '!' && next == '=') { tok.type = TOK_NE;     lex->pos += 2; }
        else if (c == '<' && next == '=') { tok.type = TOK_LE;     lex->pos += 2; }
        else if (c == '>' && next == '=') { tok.type = TOK_GE;     lex->pos += 2; }
        else if (c == '&' && next == '&') { tok.type = TOK_AND;    lex->pos += 2; }
        else if (c == '|' && next == '|') { tok.type = TOK_OR;     lex->pos += 2; }
        // Single-character
        else if (c == '+')  { tok.type = TOK_PLUS;      lex->pos++; }
        else if (c == '-')  { tok.type = TOK_MINUS;     lex->pos++; }
        else if (c == '*')  { tok.type = TOK_STAR;      lex->pos++; }
        else if (c == '/')  { tok.type = TOK_SLASH;     lex->pos++; }
        else if (c == '=')  { tok.type = TOK_ASSIGN;    lex->pos++; }
        else if (c == '!')  { tok.type = TOK_NOT;       lex->pos++; }
        else if (c == '<')  { tok.type = TOK_LT;        lex->pos++; }
        else if (c == '>')  { tok.type = TOK_GT;        lex->pos++; }
        else if (c == '(')  { tok.type = TOK_LPAREN;    lex->pos++; }
        else if (c == ')')  { tok.type = TOK_RPAREN;    lex->pos++; }
        else if (c == '{')  { tok.type = TOK_LBRACE;    lex->pos++; }
        else if (c == '}')  { tok.type = TOK_RBRACE;    lex->pos++; }
        else if (c == ';')  { tok.type = TOK_SEMICOLON; lex->pos++; }
        else if (c == ',')  { tok.type = TOK_COMMA;     lex->pos++; }
        else if (c == ':')  { tok.type = TOK_COLON;     lex->pos++; }
        else                { lex->pos++; continue; }

        lex->tokens[lex->tokens_count++] = tok;
    }

    // EOF
    Token eof_tok;
    memset(&eof_tok, 0, sizeof(eof_tok));
    eof_tok.type = TOK_EOF;
    lex->tokens[lex->tokens_count++] = eof_tok;

    return lex;
}

// ============================================================
// Part 2: PARSER
// ============================================================

#define AST_PROGRAM    1
#define AST_FUNC       2
#define AST_VAR        3
#define AST_BINOP      4
#define AST_LITERAL    5
#define AST_IDENT      6
#define AST_CALL       7
#define AST_IF         8
#define AST_WHILE      9
#define AST_RETURN     10
#define AST_EXPR_STMT  11
#define AST_ASSIGN     12
#define AST_STRING     13

typedef struct ASTNode {
    int   type;
    char  name[256];      // func/var/ident name
    char  type_name[64];  // type annotation: "i64", "string"
    int   value;          // integer literal value
    int   op;             // operator for BINOP
    int   then_count;     // for IF: # of "then" children (rest are "else")
    char  str_val[1024];  // string literal value

    struct ASTNode  *left;   // condition (IF/WHILE), left of binop
    struct ASTNode  *right;  // right of binop, var initializer
    struct ASTNode **children;
    int   children_count;

    // Function parameters (up to 16)
    char  param_names[16][256];
    char  param_types[16][64];
    int   params_count;
} ASTNode;

static ASTNode* new_node(int type) {
    ASTNode *n = (ASTNode *)calloc(1, sizeof(ASTNode));
    n->type     = type;
    n->children = (ASTNode **)calloc(512, sizeof(ASTNode *));
    return n;
}

typedef struct {
    Token *tokens;
    int    pos;
    int    count;
} Parser;

static Token* tok_cur(Parser *p) {
    int i = (p->pos < p->count) ? p->pos : p->count - 1;
    return &p->tokens[i];
}
static void tok_adv(Parser *p) {
    if (p->pos < p->count - 1) p->pos++;
}
static int tok_match(Parser *p, int type) { return tok_cur(p)->type == type; }
static int tok_consume(Parser *p, int type) {
    if (tok_match(p, type)) { tok_adv(p); return 1; }
    return 0;
}

// Forward declarations
static ASTNode* parse_stmt(Parser *p);
static ASTNode* parse_expr(Parser *p);
static ASTNode* parse_and(Parser *p);
static ASTNode* parse_cmp(Parser *p);
static ASTNode* parse_add(Parser *p);
static ASTNode* parse_mul(Parser *p);
static ASTNode* parse_primary(Parser *p);

static ASTNode* parse_program(Parser *p) {
    ASTNode *prog = new_node(AST_PROGRAM);

    while (tok_match(p, TOK_FN)) {
        tok_adv(p);  // consume 'fn'
        ASTNode *fn = new_node(AST_FUNC);

        // Function name
        if (tok_match(p, TOK_IDENT)) {
            strcpy(fn->name, tok_cur(p)->name);
            tok_adv(p);
        }

        // Parameters
        tok_consume(p, TOK_LPAREN);
        while (!tok_match(p, TOK_RPAREN) && !tok_match(p, TOK_EOF)) {
            if (!tok_match(p, TOK_IDENT)) break;
            int pi = fn->params_count;
            strcpy(fn->param_names[pi], tok_cur(p)->name);
            tok_adv(p);
            tok_consume(p, TOK_COLON);
            if (tok_match(p, TOK_IDENT)) {
                strcpy(fn->param_types[pi], tok_cur(p)->name);
                tok_adv(p);
            }
            fn->params_count++;
            tok_consume(p, TOK_COMMA);
        }
        tok_consume(p, TOK_RPAREN);

        // Return type
        tok_consume(p, TOK_ARROW);
        if (tok_match(p, TOK_IDENT)) {
            strcpy(fn->type_name, tok_cur(p)->name);
            tok_adv(p);
        }

        // Body
        tok_consume(p, TOK_LBRACE);
        while (!tok_match(p, TOK_RBRACE) && !tok_match(p, TOK_EOF)) {
            fn->children[fn->children_count++] = parse_stmt(p);
        }
        tok_consume(p, TOK_RBRACE);

        prog->children[prog->children_count++] = fn;
    }

    return prog;
}

static ASTNode* parse_stmt(Parser *p) {
    // var name: type = expr;
    if (tok_match(p, TOK_VAR)) {
        tok_adv(p);
        ASTNode *n = new_node(AST_VAR);
        if (tok_match(p, TOK_IDENT)) { strcpy(n->name, tok_cur(p)->name); tok_adv(p); }
        tok_consume(p, TOK_COLON);
        if (tok_match(p, TOK_IDENT)) { strcpy(n->type_name, tok_cur(p)->name); tok_adv(p); }
        if (tok_consume(p, TOK_ASSIGN)) n->right = parse_expr(p);
        tok_consume(p, TOK_SEMICOLON);
        return n;
    }

    // let name = expr;
    if (tok_match(p, TOK_LET)) {
        tok_adv(p);
        ASTNode *n = new_node(AST_VAR);
        if (tok_match(p, TOK_IDENT)) { strcpy(n->name, tok_cur(p)->name); tok_adv(p); }
        strcpy(n->type_name, "auto");
        tok_consume(p, TOK_ASSIGN);
        n->right = parse_expr(p);
        tok_consume(p, TOK_SEMICOLON);
        return n;
    }

    // return expr;
    if (tok_match(p, TOK_RETURN)) {
        tok_adv(p);
        ASTNode *n = new_node(AST_RETURN);
        if (!tok_match(p, TOK_SEMICOLON)) n->right = parse_expr(p);
        tok_consume(p, TOK_SEMICOLON);
        return n;
    }

    // if (cond) { ... } else { ... }
    if (tok_match(p, TOK_IF)) {
        tok_adv(p);
        ASTNode *n = new_node(AST_IF);
        tok_consume(p, TOK_LPAREN);
        n->left = parse_expr(p);
        tok_consume(p, TOK_RPAREN);

        tok_consume(p, TOK_LBRACE);
        while (!tok_match(p, TOK_RBRACE) && !tok_match(p, TOK_EOF))
            n->children[n->children_count++] = parse_stmt(p);
        tok_consume(p, TOK_RBRACE);
        n->then_count = n->children_count;

        if (tok_consume(p, TOK_ELSE)) {
            tok_consume(p, TOK_LBRACE);
            while (!tok_match(p, TOK_RBRACE) && !tok_match(p, TOK_EOF))
                n->children[n->children_count++] = parse_stmt(p);
            tok_consume(p, TOK_RBRACE);
        }
        return n;
    }

    // while (cond) { ... }
    if (tok_match(p, TOK_WHILE)) {
        tok_adv(p);
        ASTNode *n = new_node(AST_WHILE);
        tok_consume(p, TOK_LPAREN);
        n->left = parse_expr(p);
        tok_consume(p, TOK_RPAREN);

        tok_consume(p, TOK_LBRACE);
        while (!tok_match(p, TOK_RBRACE) && !tok_match(p, TOK_EOF))
            n->children[n->children_count++] = parse_stmt(p);
        tok_consume(p, TOK_RBRACE);
        return n;
    }

    // Assignment: ident = expr;
    if (tok_match(p, TOK_IDENT) && p->pos + 1 < p->count &&
        p->tokens[p->pos + 1].type == TOK_ASSIGN) {
        ASTNode *n = new_node(AST_ASSIGN);
        strcpy(n->name, tok_cur(p)->name);
        tok_adv(p);  // ident
        tok_adv(p);  // '='
        n->right = parse_expr(p);
        tok_consume(p, TOK_SEMICOLON);
        return n;
    }

    // Expression statement
    ASTNode *n = new_node(AST_EXPR_STMT);
    n->right = parse_expr(p);
    tok_consume(p, TOK_SEMICOLON);
    return n;
}

// Precedence: expr > and > cmp > add > mul > primary
static ASTNode* parse_expr(Parser *p) {
    ASTNode *left = parse_and(p);
    while (tok_match(p, TOK_OR)) {
        ASTNode *n = new_node(AST_BINOP);
        n->op = TOK_OR; tok_adv(p);
        n->left = left;
        n->right = parse_and(p);
        left = n;
    }
    return left;
}

static ASTNode* parse_and(Parser *p) {
    ASTNode *left = parse_cmp(p);
    while (tok_match(p, TOK_AND)) {
        ASTNode *n = new_node(AST_BINOP);
        n->op = TOK_AND; tok_adv(p);
        n->left = left;
        n->right = parse_cmp(p);
        left = n;
    }
    return left;
}

static ASTNode* parse_cmp(Parser *p) {
    ASTNode *left = parse_add(p);
    if (tok_match(p, TOK_EQ) || tok_match(p, TOK_NE) || tok_match(p, TOK_LT) ||
        tok_match(p, TOK_GT) || tok_match(p, TOK_LE) || tok_match(p, TOK_GE)) {
        ASTNode *n = new_node(AST_BINOP);
        n->op = tok_cur(p)->type; tok_adv(p);
        n->left = left;
        n->right = parse_add(p);
        return n;
    }
    return left;
}

static ASTNode* parse_add(Parser *p) {
    ASTNode *left = parse_mul(p);
    while (tok_match(p, TOK_PLUS) || tok_match(p, TOK_MINUS)) {
        ASTNode *n = new_node(AST_BINOP);
        n->op = tok_cur(p)->type; tok_adv(p);
        n->left = left;
        n->right = parse_mul(p);
        left = n;
    }
    return left;
}

static ASTNode* parse_mul(Parser *p) {
    ASTNode *left = parse_primary(p);
    while (tok_match(p, TOK_STAR) || tok_match(p, TOK_SLASH)) {
        ASTNode *n = new_node(AST_BINOP);
        n->op = tok_cur(p)->type; tok_adv(p);
        n->left = left;
        n->right = parse_primary(p);
        left = n;
    }
    return left;
}

static ASTNode* parse_primary(Parser *p) {
    // Integer literal
    if (tok_match(p, TOK_INT)) {
        ASTNode *n = new_node(AST_LITERAL);
        n->value = tok_cur(p)->value;
        tok_adv(p);
        return n;
    }

    // String literal
    if (tok_match(p, TOK_STRING)) {
        ASTNode *n = new_node(AST_STRING);
        strcpy(n->str_val, tok_cur(p)->str_val);
        tok_adv(p);
        return n;
    }

    // Identifier or function call
    if (tok_match(p, TOK_IDENT)) {
        ASTNode *n = new_node(AST_IDENT);
        strcpy(n->name, tok_cur(p)->name);
        tok_adv(p);

        if (tok_consume(p, TOK_LPAREN)) {
            n->type = AST_CALL;
            while (!tok_match(p, TOK_RPAREN) && !tok_match(p, TOK_EOF)) {
                n->children[n->children_count++] = parse_expr(p);
                tok_consume(p, TOK_COMMA);
            }
            tok_consume(p, TOK_RPAREN);
        }
        return n;
    }

    // Parenthesized expression
    if (tok_consume(p, TOK_LPAREN)) {
        ASTNode *e = parse_expr(p);
        tok_consume(p, TOK_RPAREN);
        return e;
    }

    // Unary NOT
    if (tok_match(p, TOK_NOT)) {
        tok_adv(p);
        ASTNode *n = new_node(AST_BINOP);
        n->op = TOK_NOT;
        n->right = parse_primary(p);
        return n;
    }

    // Unary minus
    if (tok_match(p, TOK_MINUS)) {
        tok_adv(p);
        ASTNode *n = new_node(AST_BINOP);
        n->op = TOK_MINUS;
        ASTNode *zero = new_node(AST_LITERAL);
        zero->value = 0;
        n->left  = zero;
        n->right = parse_primary(p);
        return n;
    }

    // Invalid
    ASTNode *n = new_node(0);
    return n;
}

// ============================================================
// Part 3: CODEGEN
// ============================================================

// Direct-append output buffer
#define OUTPUT_SIZE 1000000
static char output_buf[OUTPUT_SIZE];
static int  output_pos = 0;

static void out(const char *s) {
    if (!s) return;
    size_t len = strlen(s);
    if (output_pos + (int)len < OUTPUT_SIZE - 1) {
        memcpy(output_buf + output_pos, s, len);
        output_pos += (int)len;
        output_buf[output_pos] = '\0';
    }
}

static void out_char(char c) {
    if (output_pos < OUTPUT_SIZE - 2) {
        output_buf[output_pos++] = c;
        output_buf[output_pos]   = '\0';
    }
}

// Map FreeLang type to C type
static const char* fl_type_to_c(const char *fl) {
    if (!fl || fl[0] == '\0') return "long";
    if (strcmp(fl, "i64")    == 0) return "long";
    if (strcmp(fl, "i32")    == 0) return "int";
    if (strcmp(fl, "f64")    == 0) return "double";
    if (strcmp(fl, "bool")   == 0) return "int";
    if (strcmp(fl, "string") == 0) return "const char*";
    if (strcmp(fl, "auto")   == 0) return "long";  // default
    return "long";
}

// Check if a function is 'main'
static int is_main_func(ASTNode *fn) {
    return strcmp(fn->name, "main") == 0;
}

// Codegen expression -> returns malloc'd string (caller does NOT need to free)
// Uses an expression pool to avoid malloc overhead
#define EPOOL_SIZE 64
#define EPOOL_BUFSIZE 4096
static char  epool[EPOOL_SIZE][EPOOL_BUFSIZE];
static int   epool_depth = 0;

static char* gen_expr(ASTNode *ast);

static char* epool_alloc(void) {
    int idx = epool_depth % EPOOL_SIZE;
    epool_depth++;
    epool[idx][0] = '\0';
    return epool[idx];
}

static void epool_release(void) {
    if (epool_depth > 0) epool_depth--;
}

static const char* op_str(int op) {
    switch (op) {
        case TOK_PLUS:  return "+";
        case TOK_MINUS: return "-";
        case TOK_STAR:  return "*";
        case TOK_SLASH: return "/";
        case TOK_EQ:    return "==";
        case TOK_NE:    return "!=";
        case TOK_LT:    return "<";
        case TOK_GT:    return ">";
        case TOK_LE:    return "<=";
        case TOK_GE:    return ">=";
        case TOK_AND:   return "&&";
        case TOK_OR:    return "||";
    }
    return "?";
}

static char* gen_expr(ASTNode *ast) {
    char *buf = epool_alloc();

    if (!ast || ast->type == 0) {
        strcpy(buf, "0");
        return buf;
    }

    switch (ast->type) {
        case AST_LITERAL: {
            snprintf(buf, EPOOL_BUFSIZE, "%d", ast->value);
            break;
        }
        case AST_STRING: {
            snprintf(buf, EPOOL_BUFSIZE, "\"%s\"", ast->str_val);
            break;
        }
        case AST_IDENT: {
            snprintf(buf, EPOOL_BUFSIZE, "%s", ast->name);
            break;
        }
        case AST_CALL: {
            // Build args string
            char args[EPOOL_BUFSIZE] = "";
            for (int i = 0; i < ast->children_count; i++) {
                if (i > 0) strncat(args, ", ", EPOOL_BUFSIZE - strlen(args) - 1);
                char *arg = gen_expr(ast->children[i]);
                strncat(args, arg, EPOOL_BUFSIZE - strlen(args) - 1);
                epool_release();
            }
            snprintf(buf, EPOOL_BUFSIZE, "%s(%s)", ast->name, args);
            break;
        }
        case AST_BINOP: {
            if (ast->op == TOK_NOT) {
                // Unary NOT
                char *right = gen_expr(ast->right);
                snprintf(buf, EPOOL_BUFSIZE, "(!%s)", right);
                epool_release();
            } else {
                char *left  = gen_expr(ast->left);
                char left_copy[EPOOL_BUFSIZE];
                strncpy(left_copy, left, EPOOL_BUFSIZE - 1);
                epool_release();

                char *right = gen_expr(ast->right);
                snprintf(buf, EPOOL_BUFSIZE, "(%s %s %s)",
                         left_copy, op_str(ast->op), right);
                epool_release();
            }
            break;
        }
        default:
            strcpy(buf, "0");
            break;
    }

    return buf;
}

// Forward declaration
static void gen_stmts(ASTNode **stmts, int count, int indent);

static void indent_out(int level) {
    for (int i = 0; i < level; i++) out("    ");
}

static void gen_stmt(ASTNode *ast, int indent) {
    if (!ast) return;

    switch (ast->type) {
        case AST_VAR: {
            const char *ctype = fl_type_to_c(ast->type_name);
            indent_out(indent);
            out(ctype); out(" "); out(ast->name);
            if (ast->right) {
                out(" = ");
                char *e = gen_expr(ast->right);
                out(e);
                epool_release();
            }
            out(";\n");
            break;
        }
        case AST_ASSIGN: {
            indent_out(indent);
            out(ast->name); out(" = ");
            char *e = gen_expr(ast->right);
            out(e);
            epool_release();
            out(";\n");
            break;
        }
        case AST_RETURN: {
            indent_out(indent);
            if (ast->right) {
                out("return ");
                char *e = gen_expr(ast->right);
                out(e);
                epool_release();
                out(";\n");
            } else {
                out("return;\n");
            }
            break;
        }
        case AST_IF: {
            indent_out(indent);
            out("if (");
            char *cond = gen_expr(ast->left);
            out(cond);
            epool_release();
            out(") {\n");

            // then block
            gen_stmts(ast->children, ast->then_count, indent + 1);

            if (ast->children_count > ast->then_count) {
                // else block
                indent_out(indent);
                out("} else {\n");
                gen_stmts(ast->children + ast->then_count,
                          ast->children_count - ast->then_count,
                          indent + 1);
            }

            indent_out(indent);
            out("}\n");
            break;
        }
        case AST_WHILE: {
            indent_out(indent);
            out("while (");
            char *cond = gen_expr(ast->left);
            out(cond);
            epool_release();
            out(") {\n");
            gen_stmts(ast->children, ast->children_count, indent + 1);
            indent_out(indent);
            out("}\n");
            break;
        }
        case AST_EXPR_STMT: {
            if (ast->right) {
                indent_out(indent);
                char *e = gen_expr(ast->right);
                out(e);
                epool_release();
                out(";\n");
            }
            break;
        }
        default:
            break;
    }
}

static void gen_stmts(ASTNode **stmts, int count, int indent) {
    for (int i = 0; i < count; i++) gen_stmt(stmts[i], indent);
}

static void gen_function(ASTNode *fn) {
    const char *ret_type = fl_type_to_c(fn->type_name);

    // main() must return int in C
    if (is_main_func(fn)) ret_type = "int";

    out(ret_type);
    out(" ");
    out(fn->name);
    out("(");

    if (fn->params_count == 0) {
        if (is_main_func(fn))
            out("void");
        else
            out("void");
    } else {
        for (int i = 0; i < fn->params_count; i++) {
            if (i > 0) out(", ");
            out(fl_type_to_c(fn->param_types[i]));
            out(" ");
            out(fn->param_names[i]);
        }
    }

    out(") {\n");
    gen_stmts(fn->children, fn->children_count, 1);
    out("}\n\n");
}

// Forward declarations for all functions
static void gen_forward_decl(ASTNode *fn) {
    const char *ret_type = fl_type_to_c(fn->type_name);
    if (is_main_func(fn)) ret_type = "int";

    out(ret_type); out(" "); out(fn->name); out("(");

    if (fn->params_count == 0) {
        out("void");
    } else {
        for (int i = 0; i < fn->params_count; i++) {
            if (i > 0) out(", ");
            out(fl_type_to_c(fn->param_types[i]));
            out(" ");
            out(fn->param_names[i]);
        }
    }
    out(");\n");
}

static char* codegen(ASTNode *prog) {
    output_pos = 0;
    output_buf[0] = '\0';
    epool_depth = 0;

    // Headers
    out("#include <stdio.h>\n");
    out("#include <stdlib.h>\n");
    out("#include <string.h>\n");
    out("#include <stdint.h>\n");
    out("\n");

    // Forward declarations
    out("/* Forward declarations */\n");
    for (int i = 0; i < prog->children_count; i++) {
        ASTNode *fn = prog->children[i];
        if (fn->type == AST_FUNC) gen_forward_decl(fn);
    }
    out("\n");

    // Function definitions (non-main first, then main)
    for (int pass = 0; pass < 2; pass++) {
        for (int i = 0; i < prog->children_count; i++) {
            ASTNode *fn = prog->children[i];
            if (fn->type != AST_FUNC) continue;
            int main_fn = is_main_func(fn);
            if (pass == 0 && main_fn)  continue;
            if (pass == 1 && !main_fn) continue;
            gen_function(fn);
        }
    }

    return output_buf;
}

// ============================================================
// Part 4: MAIN
// ============================================================

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input.fl> [output.c]\n", argv[0]);
        fprintf(stderr, "       %s <input.fl>           (outputs to stdout)\n", argv[0]);
        return 1;
    }

    // Read input file
    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open '%s'\n", argv[1]);
        return 1;
    }
    fseek(fp, 0, SEEK_END);
    long fsz = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    char *src = (char *)malloc(fsz + 1);
    if (!src) { fclose(fp); fprintf(stderr, "Out of memory\n"); return 1; }
    fread(src, 1, fsz, fp);
    src[fsz] = '\0';
    fclose(fp);

    // Tokenize
    Lexer *lex = tokenize(src);

    // Parse
    Parser parser;
    parser.tokens = lex->tokens;
    parser.pos    = 0;
    parser.count  = lex->tokens_count;
    ASTNode *prog = parse_program(&parser);

    // Codegen
    char *c_code = codegen(prog);

    // Output
    if (argc >= 3) {
        FILE *out_fp = fopen(argv[2], "w");
        if (!out_fp) {
            fprintf(stderr, "Error: Cannot write '%s'\n", argv[2]);
            return 1;
        }
        fputs(c_code, out_fp);
        fclose(out_fp);
        fprintf(stderr, "Generated: %s\n", argv[2]);
    } else {
        fputs(c_code, stdout);
    }

    // Cleanup
    free(src);
    free(lex->tokens);
    free(lex);

    return 0;
}

