// ============================================================
// minicc.c - Mini Compiler for FreeLang (Fixed v2)
// Compiles a subset of FreeLang to C
// ============================================================

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// ============================================================
// Part 1: LEXER
// ============================================================

#define TOK_EOF       0
#define TOK_INT       1
#define TOK_IDENT     2
#define TOK_PLUS      3
#define TOK_MINUS     4
#define TOK_STAR      5
#define TOK_SLASH     6
#define TOK_EQ        7
#define TOK_NE        8
#define TOK_LT        9
#define TOK_GT        10
#define TOK_LE        11
#define TOK_GE        12
#define TOK_ASSIGN    13
#define TOK_LPAREN    14
#define TOK_RPAREN    15
#define TOK_LBRACE    16
#define TOK_RBRACE    17
#define TOK_SEMICOLON 18
#define TOK_COMMA     19
#define TOK_COLON     20
#define TOK_AND       21
#define TOK_OR        22
#define TOK_NOT       23
#define TOK_FN        24
#define TOK_LET       25
#define TOK_VAR       26
#define TOK_RETURN    27
#define TOK_IF        28
#define TOK_ELSE      29
#define TOK_WHILE     30
#define TOK_FOR       31
#define TOK_MATCH     32
#define TOK_ARROW     33
#define TOK_STRING    34

typedef struct {
    int  type;
    int  value;
    char name[256];
    char str_val[1024];
} Token;

typedef struct {
    const char *input;
    int         pos;
    int         length;
    Token      *tokens;
    int         tokens_count;
} Lexer;

static int c_isdigit2(char c) { return c >= '0' && c <= '9'; }
static int c_isalpha2(char c) { return (c>='A'&&c<='Z') || (c>='a'&&c<='z'); }
static int c_isalnum2(char c) { return c_isalpha2(c) || c_isdigit2(c); }
static int c_isspace2(char c) { return c==' '||c=='\t'||c=='\n'||c=='\r'; }

static int classify_keyword(const char *n) {
    if (strcmp(n,"fn")==0)     return TOK_FN;
    if (strcmp(n,"let")==0)    return TOK_LET;
    if (strcmp(n,"var")==0)    return TOK_VAR;
    if (strcmp(n,"return")==0) return TOK_RETURN;
    if (strcmp(n,"if")==0)     return TOK_IF;
    if (strcmp(n,"else")==0)   return TOK_ELSE;
    if (strcmp(n,"while")==0)  return TOK_WHILE;
    if (strcmp(n,"for")==0)    return TOK_FOR;
    if (strcmp(n,"match")==0)  return TOK_MATCH;
    return 0;
}

Lexer* tokenize(const char *input) {
    Lexer *lex = (Lexer *)calloc(1, sizeof(Lexer));
    lex->input  = input;
    lex->length = (int)strlen(input);
    lex->tokens = (Token *)calloc(10000, sizeof(Token));

    while (lex->pos < lex->length) {
        char c = input[lex->pos];
        if (c == '\0') break;
        if (c_isspace2(c)) { lex->pos++; continue; }

        // Line comment
        if (c=='/' && lex->pos+1<lex->length && input[lex->pos+1]=='/') {
            while (lex->pos<lex->length && input[lex->pos]!='\n') lex->pos++;
            continue;
        }

        Token tok;
        memset(&tok, 0, sizeof(tok));

        if (c_isdigit2(c)) {
            while (lex->pos<lex->length && c_isdigit2(input[lex->pos]))
                tok.value = tok.value*10 + (input[lex->pos++]-'0');
            tok.type = TOK_INT;
            lex->tokens[lex->tokens_count++] = tok;
            continue;
        }

        if (c_isalpha2(c) || c=='_') {
            int len=0;
            while (lex->pos<lex->length && (c_isalnum2(input[lex->pos])||input[lex->pos]=='_'))
                tok.name[len++] = input[lex->pos++];
            int kw = classify_keyword(tok.name);
            tok.type = kw ? kw : TOK_IDENT;
            lex->tokens[lex->tokens_count++] = tok;
            continue;
        }

        if (c == '"') {
            lex->pos++;
            int len=0;
            while (lex->pos<lex->length && input[lex->pos]!='"' && len<1023) {
                if (input[lex->pos]=='\\' && lex->pos+1<lex->length) {
                    lex->pos++;
                    char e=input[lex->pos++];
                    tok.str_val[len++]=(e=='n'?'\n':(e=='t'?'\t':e));
                } else {
                    tok.str_val[len++]=input[lex->pos++];
                }
            }
            if (lex->pos<lex->length) lex->pos++;
            tok.type=TOK_STRING;
            lex->tokens[lex->tokens_count++]=tok;
            continue;
        }

        char nx = (lex->pos+1<lex->length)?input[lex->pos+1]:0;
        if      (c=='-'&&nx=='>') { tok.type=TOK_ARROW;  lex->pos+=2; }
        else if (c=='='&&nx=='=') { tok.type=TOK_EQ;     lex->pos+=2; }
        else if (c=='!'&&nx=='=') { tok.type=TOK_NE;     lex->pos+=2; }
        else if (c=='<'&&nx=='=') { tok.type=TOK_LE;     lex->pos+=2; }
        else if (c=='>'&&nx=='=') { tok.type=TOK_GE;     lex->pos+=2; }
        else if (c=='&'&&nx=='&') { tok.type=TOK_AND;    lex->pos+=2; }
        else if (c=='|'&&nx=='|') { tok.type=TOK_OR;     lex->pos+=2; }
        else if (c=='+') { tok.type=TOK_PLUS;      lex->pos++; }
        else if (c=='-') { tok.type=TOK_MINUS;     lex->pos++; }
        else if (c=='*') { tok.type=TOK_STAR;      lex->pos++; }
        else if (c=='/') { tok.type=TOK_SLASH;     lex->pos++; }
        else if (c=='=') { tok.type=TOK_ASSIGN;    lex->pos++; }
        else if (c=='!') { tok.type=TOK_NOT;       lex->pos++; }
        else if (c=='<') { tok.type=TOK_LT;        lex->pos++; }
        else if (c=='>') { tok.type=TOK_GT;        lex->pos++; }
        else if (c=='(') { tok.type=TOK_LPAREN;    lex->pos++; }
        else if (c==')') { tok.type=TOK_RPAREN;    lex->pos++; }
        else if (c=='{') { tok.type=TOK_LBRACE;    lex->pos++; }
        else if (c=='}') { tok.type=TOK_RBRACE;    lex->pos++; }
        else if (c==';') { tok.type=TOK_SEMICOLON; lex->pos++; }
        else if (c==',') { tok.type=TOK_COMMA;     lex->pos++; }
        else if (c==':') { tok.type=TOK_COLON;     lex->pos++; }
        else             { lex->pos++; continue; }
        lex->tokens[lex->tokens_count++] = tok;
    }

    Token eof; memset(&eof,0,sizeof(eof)); eof.type=TOK_EOF;
    lex->tokens[lex->tokens_count++] = eof;
    return lex;
}

// ============================================================
// Part 2: PARSER
// ============================================================

#define AST_PROGRAM    1
#define AST_FUNC       2
#define AST_VAR        3
#define AST_BINOP      4
#define AST_LITERAL    5
#define AST_IDENT      6
#define AST_CALL       7
#define AST_IF         8
#define AST_WHILE      9
#define AST_RETURN     10
#define AST_EXPR_STMT  11
#define AST_ASSIGN     12
#define AST_STRING     13

typedef struct ASTNode {
    int  type;
    char name[256];
    char type_name[64];
    int  value;
    int  op;
    int  then_count;
    char str_val[1024];
    struct ASTNode  *left;
    struct ASTNode  *right;
    struct ASTNode **children;
    int  children_count;
    char param_names[16][256];
    char param_types[16][64];
    int  params_count;
} ASTNode;

static ASTNode* new_node(int type) {
    ASTNode *n = (ASTNode *)calloc(1, sizeof(ASTNode));
    n->type     = type;
    n->children = (ASTNode **)calloc(512, sizeof(ASTNode *));
    return n;
}

typedef struct { Token *tokens; int pos; int count; } Parser;

static Token* tcur(Parser *p) {
    int i=(p->pos<p->count)?p->pos:p->count-1; return &p->tokens[i];
}
static void tadv(Parser *p) { if (p->pos<p->count-1) p->pos++; }
static int  tmatch(Parser *p, int t) { return tcur(p)->type==t; }
static int  tconsume(Parser *p, int t) { if(tmatch(p,t)){tadv(p);return 1;} return 0; }

static ASTNode* parse_stmt(Parser *p);
static ASTNode* parse_expr(Parser *p);
static ASTNode* parse_and_expr(Parser *p);
static ASTNode* parse_cmp(Parser *p);
static ASTNode* parse_add(Parser *p);
static ASTNode* parse_mul(Parser *p);
static ASTNode* parse_primary(Parser *p);

static ASTNode* parse_program(Parser *p) {
    ASTNode *prog = new_node(AST_PROGRAM);
    while (tmatch(p, TOK_FN)) {
        tadv(p);
        ASTNode *fn = new_node(AST_FUNC);
        if (tmatch(p,TOK_IDENT)) { strcpy(fn->name,tcur(p)->name); tadv(p); }
        tconsume(p,TOK_LPAREN);
        while (!tmatch(p,TOK_RPAREN) && !tmatch(p,TOK_EOF)) {
            if (!tmatch(p,TOK_IDENT)) break;
            int pi=fn->params_count;
            strcpy(fn->param_names[pi],tcur(p)->name); tadv(p);
            tconsume(p,TOK_COLON);
            if (tmatch(p,TOK_IDENT)){strcpy(fn->param_types[pi],tcur(p)->name);tadv(p);}
            fn->params_count++;
            tconsume(p,TOK_COMMA);
        }
        tconsume(p,TOK_RPAREN);
        tconsume(p,TOK_ARROW);
        if (tmatch(p,TOK_IDENT)){strcpy(fn->type_name,tcur(p)->name);tadv(p);}
        tconsume(p,TOK_LBRACE);
        while (!tmatch(p,TOK_RBRACE) && !tmatch(p,TOK_EOF))
            fn->children[fn->children_count++]=parse_stmt(p);
        tconsume(p,TOK_RBRACE);
        prog->children[prog->children_count++]=fn;
    }
    return prog;
}

static ASTNode* parse_stmt(Parser *p) {
    if (tmatch(p,TOK_VAR)) {
        tadv(p);
        ASTNode *n=new_node(AST_VAR);
        if (tmatch(p,TOK_IDENT)){strcpy(n->name,tcur(p)->name);tadv(p);}
        tconsume(p,TOK_COLON);
        if (tmatch(p,TOK_IDENT)){strcpy(n->type_name,tcur(p)->name);tadv(p);}
        if (tconsume(p,TOK_ASSIGN)) n->right=parse_expr(p);
        tconsume(p,TOK_SEMICOLON);
        return n;
    }
    if (tmatch(p,TOK_LET)) {
        tadv(p);
        ASTNode *n=new_node(AST_VAR);
        if (tmatch(p,TOK_IDENT)){strcpy(n->name,tcur(p)->name);tadv(p);}
        strcpy(n->type_name,"auto");
        tconsume(p,TOK_ASSIGN);
        n->right=parse_expr(p);
        tconsume(p,TOK_SEMICOLON);
        return n;
    }
    if (tmatch(p,TOK_RETURN)) {
        tadv(p);
        ASTNode *n=new_node(AST_RETURN);
        if (!tmatch(p,TOK_SEMICOLON)) n->right=parse_expr(p);
        tconsume(p,TOK_SEMICOLON);
        return n;
    }
    if (tmatch(p,TOK_IF)) {
        tadv(p);
        ASTNode *n=new_node(AST_IF);
        tconsume(p,TOK_LPAREN); n->left=parse_expr(p); tconsume(p,TOK_RPAREN);
        tconsume(p,TOK_LBRACE);
        while(!tmatch(p,TOK_RBRACE)&&!tmatch(p,TOK_EOF))
            n->children[n->children_count++]=parse_stmt(p);
        tconsume(p,TOK_RBRACE);
        n->then_count=n->children_count;
        if (tconsume(p,TOK_ELSE)) {
            tconsume(p,TOK_LBRACE);
            while(!tmatch(p,TOK_RBRACE)&&!tmatch(p,TOK_EOF))
                n->children[n->children_count++]=parse_stmt(p);
            tconsume(p,TOK_RBRACE);
        }
        return n;
    }
    if (tmatch(p,TOK_WHILE)) {
        tadv(p);
        ASTNode *n=new_node(AST_WHILE);
        tconsume(p,TOK_LPAREN); n->left=parse_expr(p); tconsume(p,TOK_RPAREN);
        tconsume(p,TOK_LBRACE);
        while(!tmatch(p,TOK_RBRACE)&&!tmatch(p,TOK_EOF))
            n->children[n->children_count++]=parse_stmt(p);
        tconsume(p,TOK_RBRACE);
        return n;
    }
    // Assignment: ident = expr;
    if (tmatch(p,TOK_IDENT) && p->pos+1<p->count && p->tokens[p->pos+1].type==TOK_ASSIGN) {
        ASTNode *n=new_node(AST_ASSIGN);
        strcpy(n->name,tcur(p)->name); tadv(p); tadv(p);
        n->right=parse_expr(p);
        tconsume(p,TOK_SEMICOLON);
        return n;
    }
    // Expression statement
    ASTNode *n=new_node(AST_EXPR_STMT);
    n->right=parse_expr(p);
    tconsume(p,TOK_SEMICOLON);
    return n;
}

static ASTNode* parse_expr(Parser *p) {
    ASTNode *left=parse_and_expr(p);
    while (tmatch(p,TOK_OR)) {
        ASTNode *n=new_node(AST_BINOP); n->op=TOK_OR; tadv(p);
        n->left=left; n->right=parse_and_expr(p); left=n;
    }
    return left;
}
static ASTNode* parse_and_expr(Parser *p) {
    ASTNode *left=parse_cmp(p);
    while (tmatch(p,TOK_AND)) {
        ASTNode *n=new_node(AST_BINOP); n->op=TOK_AND; tadv(p);
        n->left=left; n->right=parse_cmp(p); left=n;
    }
    return left;
}
static ASTNode* parse_cmp(Parser *p) {
    ASTNode *left=parse_add(p);
    if (tmatch(p,TOK_EQ)||tmatch(p,TOK_NE)||tmatch(p,TOK_LT)||
        tmatch(p,TOK_GT)||tmatch(p,TOK_LE)||tmatch(p,TOK_GE)) {
        ASTNode *n=new_node(AST_BINOP); n->op=tcur(p)->type; tadv(p);
        n->left=left; n->right=parse_add(p); return n;
    }
    return left;
}
static ASTNode* parse_add(Parser *p) {
    ASTNode *left=parse_mul(p);
    while (tmatch(p,TOK_PLUS)||tmatch(p,TOK_MINUS)) {
        ASTNode *n=new_node(AST_BINOP); n->op=tcur(p)->type; tadv(p);
        n->left=left; n->right=parse_mul(p); left=n;
    }
    return left;
}
static ASTNode* parse_mul(Parser *p) {
    ASTNode *left=parse_primary(p);
    while (tmatch(p,TOK_STAR)||tmatch(p,TOK_SLASH)) {
        ASTNode *n=new_node(AST_BINOP); n->op=tcur(p)->type; tadv(p);
        n->left=left; n->right=parse_primary(p); left=n;
    }
    return left;
}
static ASTNode* parse_primary(Parser *p) {
    if (tmatch(p,TOK_INT)) {
        ASTNode *n=new_node(AST_LITERAL); n->value=tcur(p)->value; tadv(p); return n;
    }
    if (tmatch(p,TOK_STRING)) {
        ASTNode *n=new_node(AST_STRING); strcpy(n->str_val,tcur(p)->str_val); tadv(p); return n;
    }
    if (tmatch(p,TOK_IDENT)) {
        ASTNode *n=new_node(AST_IDENT); strcpy(n->name,tcur(p)->name); tadv(p);
        if (tconsume(p,TOK_LPAREN)) {
            n->type=AST_CALL;
            while(!tmatch(p,TOK_RPAREN)&&!tmatch(p,TOK_EOF)) {
                n->children[n->children_count++]=parse_expr(p);
                tconsume(p,TOK_COMMA);
            }
            tconsume(p,TOK_RPAREN);
        }
        return n;
    }
    if (tconsume(p,TOK_LPAREN)) {
        ASTNode *e=parse_expr(p); tconsume(p,TOK_RPAREN); return e;
    }
    if (tmatch(p,TOK_NOT)) {
        tadv(p); ASTNode *n=new_node(AST_BINOP); n->op=TOK_NOT;
        n->right=parse_primary(p); return n;
    }
    if (tmatch(p,TOK_MINUS)) {
        tadv(p); ASTNode *n=new_node(AST_BINOP); n->op=TOK_MINUS;
        ASTNode *z=new_node(AST_LITERAL); z->value=0;
        n->left=z; n->right=parse_primary(p); return n;
    }
    return new_node(0);
}

// ============================================================
// Part 3: CODEGEN
// ============================================================

#define OUTPUT_SIZE  1000000
static char out_buf[OUTPUT_SIZE];
static int  out_pos = 0;

static void gout(const char *s) {
    if (!s) return;
    int len=(int)strlen(s);
    if (out_pos+len < OUTPUT_SIZE-1) {
        memcpy(out_buf+out_pos, s, len);
        out_pos += len;
        out_buf[out_pos] = '\0';
    }
}

static const char* fl2c(const char *fl) {
    if (!fl||!fl[0]) return "long";
    if (strcmp(fl,"i64")==0||strcmp(fl,"auto")==0) return "long";
    if (strcmp(fl,"i32")==0) return "int";
    if (strcmp(fl,"f64")==0) return "double";
    if (strcmp(fl,"bool")==0) return "int";
    if (strcmp(fl,"string")==0) return "const char*";
    return "long";
}

// Expression codegen using a simple pool
#define EP_SIZE  64
#define EP_BUFSZ 4096
static char  ep[EP_SIZE][EP_BUFSZ];
static int   ep_depth = 0;

static char* gen_expr(ASTNode *ast);

static char* ep_alloc(void) {
    char *b = ep[ep_depth % EP_SIZE];
    ep_depth++;
    b[0]='\0';
    return b;
}
static void ep_free(void) { if(ep_depth>0) ep_depth--; }

static const char* binop_str(int op) {
    switch(op){
        case TOK_PLUS:  return "+";
        case TOK_MINUS: return "-";
        case TOK_STAR:  return "*";
        case TOK_SLASH: return "/";
        case TOK_EQ:    return "==";
        case TOK_NE:    return "!=";
        case TOK_LT:    return "<";
        case TOK_GT:    return ">";
        case TOK_LE:    return "<=";
        case TOK_GE:    return ">=";
        case TOK_AND:   return "&&";
        case TOK_OR:    return "||";
    }
    return "?";
}

static char* gen_expr(ASTNode *ast) {
    char *buf = ep_alloc();
    if (!ast || ast->type==0) { strcpy(buf,"0"); return buf; }
    switch(ast->type) {
        case AST_LITERAL:
            snprintf(buf, EP_BUFSZ, "%d", ast->value);
            break;
        case AST_STRING:
            snprintf(buf, EP_BUFSZ, "\"%s\"", ast->str_val);
            break;
        case AST_IDENT:
            snprintf(buf, EP_BUFSZ, "%s", ast->name);
            break;
        case AST_CALL: {
            char args[EP_BUFSZ]="";
            for (int i=0; i<ast->children_count; i++) {
                if (i>0) strncat(args,", ",EP_BUFSZ-strlen(args)-1);
                char *a=gen_expr(ast->children[i]);
                strncat(args,a,EP_BUFSZ-strlen(args)-1);
                ep_free();
            }
            snprintf(buf, EP_BUFSZ, "%s(%s)", ast->name, args);
            break;
        }
        case AST_BINOP: {
            if (ast->op==TOK_NOT) {
                char *r=gen_expr(ast->right);
                snprintf(buf,EP_BUFSZ,"(!%s)",r);
                ep_free();
            } else {
                char *l=gen_expr(ast->left);
                char lc[EP_BUFSZ]; strncpy(lc,l,EP_BUFSZ-1); ep_free();
                char *r=gen_expr(ast->right);
                snprintf(buf,EP_BUFSZ,"(%s %s %s)",lc,binop_str(ast->op),r);
                ep_free();
            }
            break;
        }
        default: strcpy(buf,"0"); break;
    }
    return buf;
}

static void gen_stmts(ASTNode **stmts, int count, int indent);

static void ind(int level) { for(int i=0;i<level;i++) gout("    "); }

static void gen_stmt(ASTNode *ast, int indent) {
    if (!ast) return;
    switch(ast->type) {
        case AST_VAR: {
            const char *ct=fl2c(ast->type_name);
            ind(indent); gout(ct); gout(" "); gout(ast->name);
            if (ast->right) {
                gout(" = "); char *e=gen_expr(ast->right); gout(e); ep_free();
            }
            gout(";\n");
            break;
        }
        case AST_ASSIGN: {
            ind(indent); gout(ast->name); gout(" = ");
            char *e=gen_expr(ast->right); gout(e); ep_free();
            gout(";\n");
            break;
        }
        case AST_RETURN: {
            ind(indent);
            if (ast->right) {
                gout("return "); char *e=gen_expr(ast->right); gout(e); ep_free();
                gout(";\n");
            } else {
                gout("return;\n");
            }
            break;
        }
        case AST_IF: {
            ind(indent); gout("if (");
            char *c=gen_expr(ast->left); gout(c); ep_free();
            gout(") {\n");
            gen_stmts(ast->children, ast->then_count, indent+1);
            if (ast->children_count > ast->then_count) {
                ind(indent); gout("} else {\n");
                gen_stmts(ast->children+ast->then_count,
                          ast->children_count-ast->then_count, indent+1);
            }
            ind(indent); gout("}\n");
            break;
        }
        case AST_WHILE: {
            ind(indent); gout("while (");
            char *c=gen_expr(ast->left); gout(c); ep_free();
            gout(") {\n");
            gen_stmts(ast->children, ast->children_count, indent+1);
            ind(indent); gout("}\n");
            break;
        }
        case AST_EXPR_STMT: {
            if (ast->right) {
                ind(indent); char *e=gen_expr(ast->right); gout(e); ep_free();
                gout(";\n");
            }
            break;
        }
        default: break;
    }
}

static void gen_stmts(ASTNode **stmts, int count, int indent) {
    for (int i=0;i<count;i++) gen_stmt(stmts[i], indent);
}

static void gen_fwd(ASTNode *fn) {
    int is_main = (strcmp(fn->name,"main")==0);
    const char *rt = is_main ? "int" : fl2c(fn->type_name);
    gout(rt); gout(" "); gout(fn->name); gout("(");
    if (fn->params_count==0) {
        gout("void");
    } else {
        for (int i=0;i<fn->params_count;i++) {
            if (i>0) gout(", ");
            gout(fl2c(fn->param_types[i])); gout(" "); gout(fn->param_names[i]);
        }
    }
    gout(");\n");
}

static void gen_func(ASTNode *fn) {
    int is_main = (strcmp(fn->name,"main")==0);
    const char *rt = is_main ? "int" : fl2c(fn->type_name);
    gout(rt); gout(" "); gout(fn->name); gout("(");
    if (fn->params_count==0) {
        gout("void");
    } else {
        for (int i=0;i<fn->params_count;i++) {
            if (i>0) gout(", ");
            gout(fl2c(fn->param_types[i])); gout(" "); gout(fn->param_names[i]);
        }
    }
    gout(") {\n");
    gen_stmts(fn->children, fn->children_count, 1);
    gout("}\n\n");
}

static char* codegen(ASTNode *prog) {
    out_pos=0; out_buf[0]='\0'; ep_depth=0;

    gout("#include <stdio.h>\n");
    gout("#include <stdlib.h>\n");
    gout("#include <string.h>\n");
    gout("#include <stdint.h>\n\n");

    // Forward declarations
    gout("/* Forward declarations */\n");
    for (int i=0;i<prog->children_count;i++) {
        ASTNode *fn=prog->children[i];
        if (fn->type==AST_FUNC) gen_fwd(fn);
    }
    gout("\n");

    // Non-main functions first, then main
    for (int pass=0; pass<2; pass++) {
        for (int i=0;i<prog->children_count;i++) {
            ASTNode *fn=prog->children[i];
            if (fn->type!=AST_FUNC) continue;
            int is_main=(strcmp(fn->name,"main")==0);
            if (pass==0 && is_main)  continue;
            if (pass==1 && !is_main) continue;
            gen_func(fn);
        }
    }

    return out_buf;
}

// ============================================================
// Part 4: MAIN
// ============================================================

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr,"Usage: %s <input.fl> [output.c]\n",argv[0]);
        return 1;
    }
    FILE *fp=fopen(argv[1],"r");
    if (!fp) { fprintf(stderr,"Error: Cannot open '%s'\n",argv[1]); return 1; }
    fseek(fp,0,SEEK_END); long fsz=ftell(fp); fseek(fp,0,SEEK_SET);
    char *src=(char*)malloc(fsz+1);
    fread(src,1,fsz,fp); src[fsz]='\0'; fclose(fp);

    Lexer *lex = tokenize(src);
    Parser parser; parser.tokens=lex->tokens; parser.pos=0; parser.count=lex->tokens_count;
    ASTNode *prog = parse_program(&parser);
    char *code = codegen(prog);

    if (argc>=3) {
        FILE *out=fopen(argv[2],"w");
        if (!out){fprintf(stderr,"Error: Cannot write '%s'\n",argv[2]);return 1;}
        fputs(code,out); fclose(out);
        fprintf(stderr,"Generated: %s  (%d bytes)\n",argv[2],(int)strlen(code));
    } else {
        fputs(code,stdout);
    }

    free(src); free(lex->tokens); free(lex);
    return 0;
}
MINICC_EOF

